# builder/gen_ch26_p2.py
# -*- coding: utf-8 -*-

exercises = [{'num': 41, 'title': 'IP-based Rate Limiter Middleware на алгоритме Token Bucket', 'task': 'Создайте middleware `RateLimiter` (используя пакет `golang.org/x/time/rate`), который ограничивает количество запросов от одного IP-адреса.', 'theory': 'Ограничение частоты запросов (Rate Limiting) защищает сервис от DDoS, брутфорса и перегрузок. Алгоритм Token Bucket (маркерная корзина) позволяет сглаживать пиковую нагрузку (burst) и поддерживать фиксированную среднюю скорость пополнения токенов (rate). Для изоляции клиентов мапа лимитеров группируется по IP-адресам.', 'step_by_step': '1. Создадим структуру `IPRateLimiter` с `sync.RWMutex` и мапой лимитеров.\n2. Для каждого IP создадим или извлечем лимитер (например, 2 rps с burst 3).\n3. При превышении лимита вернем `429 Too Many Requests` с заголовком `Retry-After`.\n4. Проверим блокировку при серии частых запросов.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"net"\n\t"net/http"\n\t"net/http/httptest"\n\t"sync"\n\t"time"\n)\n\n// Упрощенный Token Bucket без сторонних библиотек для демонстрации принципа\ntype TokenBucket struct {\n\tmu         sync.Mutex\n\ttokens     float64\n\tcapacity   float64\n\trate       float64\n\tlastRefill time.Time\n}\n\nfunc NewTokenBucket(rate, capacity float64) *TokenBucket {\n\treturn &TokenBucket{\n\t\ttokens:     capacity,\n\t\tcapacity:   capacity,\n\t\trate:       rate,\n\t\tlastRefill: time.Now(),\n\t}\n}\n\nfunc (tb *TokenBucket) Allow() bool {\n\ttb.mu.Lock()\n\tdefer tb.mu.Unlock()\n\n\tnow := time.Now()\n\telapsed := now.Sub(tb.lastRefill).Seconds()\n\ttb.lastRefill = now\n\n\ttb.tokens += elapsed * tb.rate\n\tif tb.tokens > tb.capacity {\n\t\ttb.tokens = tb.capacity\n\t}\n\n\tif tb.tokens >= 1.0 {\n\t\ttb.tokens -= 1.0\n\t\treturn true\n\t}\n\treturn false\n}\n\ntype IPRateLimiter struct {\n\tmu      sync.RWMutex\n\tclients map[string]*TokenBucket\n}\n\nfunc NewIPRateLimiter() *IPRateLimiter {\n\treturn &IPRateLimiter{clients: make(map[string]*TokenBucket)}\n}\n\nfunc (lim *IPRateLimiter) GetLimiter(ip string) *TokenBucket {\n\tlim.mu.Lock()\n\tdefer lim.mu.Unlock()\n\tif tb, exists := lim.clients[ip]; exists {\n\t\treturn tb\n\t}\n\ttb := NewTokenBucket(2.0, 3.0) // 2 rps, burst 3\n\tlim.clients[ip] = tb\n\treturn tb\n}\n\nfunc RateLimitMiddleware(limiter *IPRateLimiter, next http.Handler) http.Handler {\n\treturn http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {\n\t\thost, _, err := net.SplitHostPort(r.RemoteAddr)\n\t\tif err != nil {\n\t\t\thost = r.RemoteAddr\n\t\t}\n\n\t\ttb := limiter.GetLimiter(host)\n\t\tif !tb.Allow() {\n\t\t\tw.Header().Set("Retry-After", "1")\n\t\t\thttp.Error(w, "Слишком много запросов (429 Too Many Requests)", http.StatusTooManyRequests)\n\t\t\treturn\n\t\t}\n\t\tnext.ServeHTTP(w, r)\n\t})\n}\n\nfunc main() {\n\tlimiter := NewIPRateLimiter()\n\thandler := RateLimitMiddleware(limiter, http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {\n\t\tfmt.Fprint(w, "Успешный ответ")\n\t}))\n\n\tts := httptest.NewServer(handler)\n\tdefer ts.Close()\n\n\tfor i := 1; i <= 5; i++ {\n\t\tres, _ := http.Get(ts.URL)\n\t\tfmt.Printf("Запрос #%d: Статус %d\\n", i, res.StatusCode)\n\t\tres.Body.Close()\n\t}\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Запрос #1: Статус 200\n# Запрос #2: Статус 200\n# Запрос #3: Статус 200\n# Запрос #4: Статус 429\n# Запрос #5: Статус 429'}], 'under_the_hood': 'Алгоритм Token Bucket при каждом обращении рассчитывает количество прибывших токенов пропорционально прошедшему дельта-времени `now.Sub(lastRefill)`, избегая фоновых таймеров.', 'pitfalls': 'В микросервисах за Nginx или AWS ALB реальный IP клиента находится в заголовке `X-Forwarded-For` или `X-Real-IP`, а `r.RemoteAddr` содержит IP внутреннего балансировщика.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему в распределенной микросервисной архитектуре Rate Limiting переносят в Redis?»\n**Ответ:** Если сервис развернут в 20 репликах за Kubernetes Ingress, локальный лимитер в памяти каждой реплики не видит общую частоту запросов клиента. Redis со скриптами Lua (Redis Cell / Token Bucket) обеспечивает глобальное согласованное состояние лимитов на весь кластер.'}, {'num': 42, 'title': 'Обработка составных Query-фильтров и параметров пагинации', 'task': 'Добавьте обработку параметров запроса (`?status=done`) и пагинацию (`?page=1&limit=10`).', 'theory': 'Фильтрация и постраничный вывод (Pagination) — фундаментальная часть проектирования RESTful списков. Запрос должен валидировать диапазоны значений (`page >= 1`, `1 <= limit <= 100`) и отсекать недопустимые значения параметров статуса.', 'step_by_step': '1. Создадим обработчик списка задач.\n2. Прочитаем параметр `status`.\n3. Спарсим `page` и `limit` с дефолтными значениями 1 и 10.\n4. Отфильтруем срез и вернем подмножество элементов.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"encoding/json"\n\t"fmt"\n\t"io"\n\t"net/http"\n\t"net/http/httptest"\n\t"strconv"\n)\n\ntype Item struct {\n\tID     int    `json:"id"`\n\tTitle  string `json:"title"`\n\tStatus string `json:"status"`\n}\n\nvar database = []Item{\n\t{1, "Сделать бэкап", "done"},\n\t{2, "Написать тесты", "done"},\n\t{3, "Обновить сертификаты", "pending"},\n\t{4, "Настроить мониторинг", "done"},\n\t{5, "Проверить логи", "pending"},\n}\n\nfunc listHandler(w http.ResponseWriter, r *http.Request) {\n\tq := r.URL.Query()\n\tstatusFilter := q.Get("status")\n\n\tpage, _ := strconv.Atoi(q.Get("page"))\n\tif page < 1 {\n\t\tpage = 1\n\t}\n\n\tlimit, _ := strconv.Atoi(q.Get("limit"))\n\tif limit < 1 || limit > 100 {\n\t\tlimit = 2\n\t}\n\n\tvar filtered []Item\n\tfor _, it := range database {\n\t\tif statusFilter == "" || it.Status == statusFilter {\n\t\t\tfiltered = append(filtered, it)\n\t\t}\n\t}\n\n\tstart := (page - 1) * limit\n\tif start > len(filtered) {\n\t\tstart = len(filtered)\n\t}\n\tend := start + limit\n\tif end > len(filtered) {\n\t\tend = len(filtered)\n\t}\n\n\tpaged := filtered[start:end]\n\n\tw.Header().Set("Content-Type", "application/json")\n\t_ = json.NewEncoder(w).Encode(map[string]any{\n\t\t"page":  page,\n\t\t"limit": limit,\n\t\t"total": len(filtered),\n\t\t"data":  paged,\n\t})\n}\n\nfunc main() {\n\tts := httptest.NewServer(http.HandlerFunc(listHandler))\n\tdefer ts.Close()\n\n\tresp, _ := http.Get(ts.URL + "/tasks?status=done&page=1&limit=2")\n\tbody, _ := io.ReadAll(resp.Body)\n\tresp.Body.Close()\n\n\tfmt.Println(string(body))\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# {"data":[{"id":1,"title":"Сделать бэкап","status":"done"},{"id":2,"title":"Написать тесты","status":"done"}],"limit":2,"page":1,"total":3}'}], 'under_the_hood': 'Срез среза `filtered[start:end]` в Go не выделяет новую память под элементы, а ссылается на существующий базовый массив.', 'pitfalls': 'Вычисление `start := (page - 1) * limit` без проверки на целочисленное переполнение (integer overflow) при передаче `page=9999999999` может вызвать панику слайса `slice bounds out of range`.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему в API возвращают метаданные total_count отдельным полем?»\n**Ответ:** Клиентскому UI (фронтенду) необходимо знать общее количество записей для расчета количества страниц `totalPages = ceil(total / limit)` и отображения номеров страниц пользователю.'}, {'num': 43, 'title': 'Health Check Endpoint с глубокой проверкой зависимостей и статусом 503', 'task': 'Напиши **health check endpoint**: `GET /health` возвращает `{"status": "ok"}`. Добавь проверку зависимостей (например, доступность in-memory store). Если store недоступен — `503 Service Unavailable`.', 'theory': 'В Kubernetes Health Check делится на:\n- **Liveness Probe**: жив ли процесс (если нет — перезапуск контейнера).\n- **Readiness Probe**: готов ли сервис принимать трафик (доступна ли БД, кэш, очередь). При отказе возвращается `503 Service Unavailable`, и балансировщик K8s временно снимает трафик с этого пода.', 'step_by_step': '1. Опишем интерфейс `Pinger` с методом `Ping() error`.\n2. Реализуем хендлер `/healthz`.\n3. При ошибке проверки вернем `503 Service Unavailable` с детализацией сбоя.\n4. Протестируем успешное состояние и деградацию сервиса.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"encoding/json"\n\t"errors"\n\t"fmt"\n\t"io"\n\t"net/http"\n\t"net/http/httptest"\n\t"sync/atomic"\n)\n\ntype HealthChecker struct {\n\tdbHealthy atomic.Bool\n}\n\nfunc (h *HealthChecker) ServeHTTP(w http.ResponseWriter, r *http.Request) {\n\tw.Header().Set("Content-Type", "application/json")\n\n\tif !h.dbHealthy.Load() {\n\t\tw.WriteHeader(http.StatusServiceUnavailable) // 503\n\t\t_ = json.NewEncoder(w).Encode(map[string]any{\n\t\t\t"status": "degraded",\n\t\t\t"error":  "database ping failure",\n\t\t})\n\t\treturn\n\t}\n\n\tw.WriteHeader(http.StatusOK) // 200\n\t_ = json.NewEncoder(w).Encode(map[string]any{\n\t\t"status": "ok",\n\t\t"checks": map[string]string{"database": "up", "redis": "up"},\n\t})\n}\n\nfunc main() {\n\thc := &HealthChecker{}\n\thc.dbHealthy.Store(true) // База здорова\n\n\tts := httptest.NewServer(hc)\n\tdefer ts.Close()\n\n\t// 1. Проверка в штатном режиме\n\tres1, _ := http.Get(ts.URL + "/healthz")\n\tb1, _ := io.ReadAll(res1.Body)\n\tres1.Body.Close()\n\tfmt.Printf("[Штатный режим]  Status: %d, Body: %s", res1.StatusCode, string(b1))\n\n\t// 2. Имитируем сбой базы данных\n\thc.dbHealthy.Store(false)\n\n\tres2, _ := http.Get(ts.URL + "/healthz")\n\tb2, _ := io.ReadAll(res2.Body)\n\tres2.Body.Close()\n\tfmt.Printf("[Сбой базы]      Status: %d, Body: %s", res2.StatusCode, string(b2))\n\t_ = errors.New("")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Штатный режим]  Status: 200, Body: {"checks":{"database":"up","redis":"up"},"status":"ok"}\n# [Сбой базы]      Status: 503, Body: {"error":"database ping failure","status":"degraded"}'}], 'under_the_hood': 'K8s Kubelet выполняет периодические HTTP GET запросы к `/healthz`. Ответ 200-399 считается успехом, любые другие коды или таймаут трактуются как сбой зонда.', 'pitfalls': 'В Liveness Probe нельзя проверять внешние зависимости (БД, чужие API)! Иначе при падении БД K8s начнет каскадно перезапускать все здоровые поды сервиса одновременно.', 'bigtech_interview': '**Вопрос с собеседования:** «В чем принципиальная разница между /live и /ready эндпоинтами в микросервисах?»\n**Ответ:** `/live` проверяет только факт отсутствия дедлоков внутри приложения (если упал — K8s перезапускает контейнер). `/ready` проверяет готовность обслуживать клиентов (прогрет ли кэш, доступна ли БД; если нет — K8s просто исключает под из маршрутизации Service, не убивая процесс).'}, {'num': 44, 'title': 'Строгая валидация заголовка Authorization в Basic Auth Middleware', 'task': 'Реализуйте middleware для базовой HTTP-аутентификации (Basic Auth), проверяя заголовок `Authorization`.', 'theory': 'Прямой разбор заголовка `Authorization: Basic <credentials>`:\n1. Заголовок должен начинаться со слова `Basic `.\n2. Подстрока после префикса декодируется из Base64.\n3. Полученная строка разделяется на `username` и `password` по первому двоеточию `:`.\n4. Сравнение выполняется в константное время.', 'step_by_step': '1. Напишем ручной парсинг заголовка `Authorization`.\n2. Декодируем base64 через `base64.StdEncoding.DecodeString`.\n3. Разделим через `strings.Cut(credentials, ":")`.\n4. Проверим работу обработчика.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"encoding/base64"\n\t"fmt"\n\t"net/http"\n\t"net/http/httptest"\n\t"strings"\n)\n\nfunc ManualBasicAuth(expectedUser, expectedPass string, next http.Handler) http.Handler {\n\treturn http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {\n\t\tauth := r.Header.Get("Authorization")\n\t\tif !strings.HasPrefix(auth, "Basic ") {\n\t\t\tw.Header().Set("WWW-Authenticate", `Basic realm="Protected Area"`)\n\t\t\thttp.Error(w, "Требуется авторизация", http.StatusUnauthorized)\n\t\t\treturn\n\t\t}\n\n\t\tpayload, err := base64.StdEncoding.DecodeString(strings.TrimPrefix(auth, "Basic "))\n\t\tif err != nil {\n\t\t\thttp.Error(w, "Некорректный base64", http.StatusBadRequest)\n\t\t\treturn\n\t\t}\n\n\t\tuser, pass, found := strings.Cut(string(payload), ":")\n\t\tif !found || user != expectedUser || pass != expectedPass {\n\t\t\thttp.Error(w, "Доступ запрещен", http.StatusUnauthorized)\n\t\t\treturn\n\t\t}\n\n\t\tnext.ServeHTTP(w, r)\n\t})\n}\n\nfunc main() {\n\thandler := ManualBasicAuth("devops", "k8s-secret", http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {\n\t\tfmt.Fprint(w, "Доступ разрешен!")\n\t}))\n\n\tts := httptest.NewServer(handler)\n\tdefer ts.Close()\n\n\treq, _ := http.NewRequest(http.MethodGet, ts.URL, nil)\n\trawCreds := base64.StdEncoding.EncodeToString([]byte("devops:k8s-secret"))\n\treq.Header.Set("Authorization", "Basic "+rawCreds)\n\n\tresp, _ := http.DefaultClient.Do(req)\n\tdefer resp.Body.Close()\n\n\tfmt.Printf("Код ответа: %d\\n", resp.StatusCode)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Код ответа: 200'}], 'under_the_hood': 'Функция `strings.Cut` в Go 1.18+ выполняет поиск первого вхождения разделителя без дополнительных аллокаций памяти под срез строк, в отличие от `strings.Split`.', 'pitfalls': 'Пароль пользователя может сам содержать символ `:`, поэтому разбивать строку нужно строго по первому разделителю (как делает `strings.Cut`), а не по всем.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему strings.Cut эффективнее strings.SplitN при разборе заголовков HTTP?»\n**Ответ:** `strings.SplitN` аллоцирует в куче срез `[]string` из двух элементов. `strings.Cut` возвращает три значения на стеке (`before, after string, found bool`), не совершая ни единой аллокации памяти.'}, {'num': 45, 'title': 'Глобальное оборачивание мультиплексора в единый Middleware для логирования всех путей', 'task': 'Оберни стандартный мультиплексор (`http.NewServeMux()`) в свой middleware. Убедись, что логируются все маршруты.', 'theory': 'Оборачивание самого `http.ServeMux` на верхнем уровне:\n```go\nrootHandler := Middleware(mux)\nhttp.ListenAndServe(addr, rootHandler)\n```\nпозволяет гарантировать, что абсолютно каждый входящий запрос (включая 404 Not Found и 405 Method Not Allowed) пройдет через логирование, сбор метрик и защиту от паник.', 'step_by_step': '1. Создадим роутер `mux := http.NewServeMux()` с двумя маршрутами.\n2. Обернем `mux` в `GlobalAccessLogger`.\n3. Запросим существующий и несуществующий маршрут.\n4. Убедимся, что оба запроса залогировались.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"net/http"\n\t"net/http/httptest"\n)\n\nfunc GlobalLogger(next http.Handler) http.Handler {\n\treturn http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {\n\t\tfmt.Printf("[Global Log] Incoming: %s %s\\n", r.Method, r.URL.Path)\n\t\tnext.ServeHTTP(w, r)\n\t})\n}\n\nfunc main() {\n\tmux := http.NewServeMux()\n\tmux.HandleFunc("/api/v1/ping", func(w http.ResponseWriter, r *http.Request) {\n\t\tfmt.Fprint(w, "pong")\n\t})\n\n\t// Оборачиваем весь ServeMux целиком\n\troot := GlobalLogger(mux)\n\n\tts := httptest.NewServer(root)\n\tdefer ts.Close()\n\n\tr1, _ := http.Get(ts.URL + "/api/v1/ping")\n\tr1.Body.Close()\n\n\t// 404 также проходит через логгер!\n\tr2, _ := http.Get(ts.URL + "/unknown-page")\n\tr2.Body.Close()\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Global Log] Incoming: GET /api/v1/ping\n# [Global Log] Incoming: GET /unknown-page'}], 'under_the_hood': '`http.ServeMux` удовлетворяет интерфейсу `http.Handler`, благодаря чему его можно передавать в любые стандартные middleware как `next`.', 'pitfalls': 'Если повесить middleware внутри каждого `HandleFunc`, то ошибки 404 (когда роут не найден в `ServeMux`) останутся незалогированными.', 'bigtech_interview': '**Вопрос с собеседования:** «В каком порядке должны располагаться глобальные middleware на корневом роутере?»\n**Ответ:** Самым внешним должен быть `RecoveryMiddleware` (чтобы ловить паники даже из логгера), затем `RequestIDMiddleware`, затем `Tracing/Metrics/LoggingMiddleware`, затем CORS/RateLimiting, и только затем аутентификация и роутер.'}, {'num': 46, 'title': 'Простейший веб-сервер с обработчиком корня и тестовой проверкой', 'task': '**Простейший веб-сервер**: Напишите HTTP-сервер, который при обращении на корень `/` возвращает текстовое сообщение `"Добро пожаловать в веб-сервер на Go!"`. Запустите его на порту `8080` с помощью `http.ListenAndServe`. Проверьте работу через браузер.', 'theory': 'Минимальный автономный веб-сервер в Go не требует внешних фреймворков. Вызов `http.HandleFunc` и `http.ListenAndServe` разворачивает полноценный многопоточный HTTP/1.1 и HTTP/2 сервер с пулом горутин.', 'step_by_step': '1. Создадим обработчик корня.\n2. Проверим `r.URL.Path == "/"`.\n3. Отправим приветственное сообщение в кодировке UTF-8.\n4. Протестируем клиентским запросом.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"io"\n\t"net/http"\n\t"net/http/httptest"\n)\n\nfunc welcomeHandler(w http.ResponseWriter, r *http.Request) {\n\tif r.URL.Path != "/" {\n\t\thttp.NotFound(w, r)\n\t\treturn\n\t}\n\tw.Header().Set("Content-Type", "text/plain; charset=utf-8")\n\tfmt.Fprint(w, "Добро пожаловать в веб-сервер на Go!")\n}\n\nfunc main() {\n\tmux := http.NewServeMux()\n\tmux.HandleFunc("/", welcomeHandler)\n\n\tts := httptest.NewServer(mux)\n\tdefer ts.Close()\n\n\tresp, _ := http.Get(ts.URL + "/")\n\tbody, _ := io.ReadAll(resp.Body)\n\tresp.Body.Close()\n\n\tfmt.Println(string(body))\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Добро пожаловать в веб-сервер на Go!'}], 'under_the_hood': 'Go компилирует веб-сервер в самодостаточный бинарник без внешних runtime-зависимостей (JVM, Node.js или Python interpreter).', 'pitfalls': 'При выводе кириллицы обязательно указывайте `charset=utf-8` в `Content-Type`, иначе устаревшие браузеры могут отобразить нечитаемые символы.', 'bigtech_interview': '**Вопрос с собеседования:** «Какова базовая модель конкурентности HTTP-сервера в Go?»\n**Ответ:** Модель `Goroutine-per-connection`: на каждое принятое входящее TCP-соединение сервер порождает отдельную легковесную горутину `go c.serve()`. Благодаря неблокирующему вводу-выводу через Netpoller сервер способен удерживать сотни тысяч одновременных соединений при минимальном расходе памяти (~4 КБ на горутину).'}, {'num': 47, 'title': 'Многоуровневая архитектура луковицы: сквозная трассировка запроса и ответа', 'task': 'Примените цепочку (chain) из нескольких middleware к вашему роутеру. Поймите порядок их выполнения (архитектура "луковицы": Request -> Auth -> Log -> Handler -> Log -> Response).', 'theory': "Порядок выполнения Middleware:\n1. Запрос движется снаружи внутрь по цепочке вызовов до `next.ServeHTTP`.\n2. Выполняется бизнес-логика в целевом Handler'е.\n3. Управление возвращается назад изнутри наружу через отложенные вызовы после `next.ServeHTTP`.", 'step_by_step': '1. Создадим два middleware: `AuthLayer` и `LogLayer`.\n2. Залогируем время входа и выхода в каждом слое.\n3. Проследим строгий порядок исполнения.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"net/http"\n\t"net/http/httptest"\n)\n\nfunc AuthLayer(next http.Handler) http.Handler {\n\treturn http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {\n\t\tfmt.Println("[Слой 1] Request -> Проверка авторизации")\n\t\tnext.ServeHTTP(w, r)\n\t\tfmt.Println("[Слой 1] Response <- Завершение авторизации")\n\t})\n}\n\nfunc LogLayer(next http.Handler) http.Handler {\n\treturn http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {\n\t\tfmt.Println("  [Слой 2] Request -> Старт замера таймингов")\n\t\tnext.ServeHTTP(w, r)\n\t\tfmt.Println("  [Слой 2] Response <- Фиксация таймингов в лог")\n\t})\n}\n\nfunc main() {\n\thandler := http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {\n\t\tfmt.Println("    [Ядро] Выполнение Handler")\n\t\tfmt.Fprint(w, "OK")\n\t})\n\n\t// Сборка луковицы\n\tchain := AuthLayer(LogLayer(handler))\n\n\tts := httptest.NewServer(chain)\n\tdefer ts.Close()\n\n\tresp, _ := http.Get(ts.URL)\n\tresp.Body.Close()\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Слой 1] Request -> Проверка авторизации\n#   [Слой 2] Request -> Старт замера таймингов\n#     [Ядро] Выполнение Handler\n#   [Слой 2] Response <- Фиксация таймингов в лог\n# [Слой 1] Response <- Завершение авторизации'}], 'under_the_hood': 'Разворачивание стека происходит естественным образом благодаря семантике вложенных вызовов функций в Go.', 'pitfalls': 'Если в слое LogLayer возникнет паника до завершения, код после `next.ServeHTTP` не выполнится без `defer`.', 'bigtech_interview': '**Вопрос с собеседования:** «Где в цепочке middleware должен находиться замер времени выполнения запроса?»\n**Ответ:** Логирующий замеряющий middleware должен быть как можно ближе к началу цепочки (но внутри Recovery), чтобы учесть время выполнения всех нижележащих middleware (валидация, парсинг тела, rate-limit, auth), а не только самого хендлера.'}, {'num': 48, 'title': 'Реализация собственного ServeMux на чистой мапе с обработкой 404', 'task': 'Напиши **custom ServeMux**: реализуй `http.Handler` с `map[string]http.Handler` и методом `Handle(pattern string, handler http.Handler)`. Обработай `404` для неизвестных путей. Покажи, что `http.ServeMux` — это тоже просто `http.Handler`.', 'theory': 'Любой маршрутизатор в Go — это обычная структура, реализующая интерфейс `http.Handler`. Внутри метода `ServeHTTP(w, r)` роутер анализирует `r.URL.Path` и делегирует выполнение найденному дочернему обработчику.', 'step_by_step': '1. Создадим структуру `CustomRouter` с мапой `routes map[string]http.Handler`.\n2. Реализуем метод `Handle(pattern, handler)`.\n3. В `ServeHTTP` найдем хендлер по точному совпадению или отдадим 404.\n4. Проверим работу кастомного роутера.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"net/http"\n\t"net/http/httptest"\n\t"sync"\n)\n\ntype CustomRouter struct {\n\tmu     sync.RWMutex\n\troutes map[string]http.Handler\n}\n\nfunc NewCustomRouter() *CustomRouter {\n\treturn &CustomRouter{routes: make(map[string]http.Handler)}\n}\n\nfunc (cr *CustomRouter) Handle(path string, h http.Handler) {\n\tcr.mu.Lock()\n\tdefer cr.mu.Unlock()\n\tcr.routes[path] = h\n}\n\nfunc (cr *CustomRouter) ServeHTTP(w http.ResponseWriter, r *http.Request) {\n\tcr.mu.RLock()\n\thandler, exists := cr.routes[r.URL.Path]\n\tcr.mu.RUnlock()\n\n\tif exists {\n\t\thandler.ServeHTTP(w, r)\n\t\treturn\n\t}\n\thttp.NotFound(w, r)\n}\n\nfunc main() {\n\trouter := NewCustomRouter()\n\trouter.Handle("/ping", http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {\n\t\tfmt.Fprint(w, "custom pong")\n\t}))\n\n\tts := httptest.NewServer(router)\n\tdefer ts.Close()\n\n\tres1, _ := http.Get(ts.URL + "/ping")\n\tres1.Body.Close()\n\tfmt.Println("Route /ping status:", res1.StatusCode)\n\n\tres2, _ := http.Get(ts.URL + "/missing")\n\tres2.Body.Close()\n\tfmt.Println("Route /missing status:", res2.StatusCode)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Route /ping status: 200\n# Route /missing status: 404'}], 'under_the_hood': 'Стандартный `http.ServeMux` устроен аналогично, но вместо плоской мапы использует дерево префиксов для поддержки поддеревьев маршрутов (`/static/`) и параметров Go 1.22.', 'pitfalls': 'Мапа без мьютекса при динамической регистрации роутов во время работы сервера вызовет панику из-за конкурентного доступа.', 'bigtech_interview': '**Вопрос с собеседования:** «Какую структуру данных используют высокопроизводительные HTTP-роутеры вроде Chi, Gin или Echo?»\n**Ответ:** Radix Tree (сжатое префиксное дерево / Patricia Trie). Оно обеспечивает поиск маршрута за время $O(k)$, где $k$ — длина строки URL, эффективно поддерживает path-переменные (`/users/:id`) и wildcard-маршруты (`/*filepath`) с нулевыми аллокациями памяти на запрос.'}, {'num': 49, 'title': 'Хиджекинг TCP-соединения через интерфейс http.Hijacker для кастомных протоколов', 'task': 'Напиши **HTTP handler с `http.Hijacker`**: "upgrade" соединения до raw TCP. После хиджека отправь произвольное сообщение по TCP и закрой. Объясни, когда это нужно (WebSocket вручную, проксирование).', 'theory': 'Интерфейс `http.Hijacker` позволяет обработчику перехватить управление сырым сетевым сокетом `net.Conn` и буфером `bufio.ReadWriter` у стандартного HTTP-сервера. После вызова `Hijack()` стандартный HTTP-движок полностью отключается от управления сокетом и больше не закрывает его автоматически.', 'step_by_step': '1. Проверим поддержку интерфейса: `hijacker, ok := w.(http.Hijacker)`.\n2. Вызовем `conn, bufrw, err := hijacker.Hijack()`.\n3. Отправим кастомные байты прямо в TCP-сокет.\n4. Вручную закроем соединение `defer conn.Close()`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"bufio"\n\t"fmt"\n\t"net/http"\n\t"net/http/httptest"\n)\n\nfunc hijackHandler(w http.ResponseWriter, r *http.Request) {\n\thijacker, ok := w.(http.Hijacker)\n\tif !ok {\n\t\thttp.Error(w, "Сервер не поддерживает Hijacking", http.StatusInternalServerError)\n\t\treturn\n\t}\n\n\t// Перехватываем контроль над сырым TCP сокетом\n\tconn, bufrw, err := hijacker.Hijack()\n\tif err != nil {\n\t\thttp.Error(w, err.Error(), http.StatusInternalServerError)\n\t\treturn\n\t}\n\tdefer conn.Close() // Обязательно закрываем сокет вручную!\n\n\t// Пишем кастомный raw-ответ прямо в сокет в обход протокола HTTP\n\t_, _ = bufrw.WriteString("HTTP/1.1 101 Switching Protocols\\r\\n")\n\t_, _ = bufrw.WriteString("Upgrade: CustomRawProto\\r\\n")\n\t_, _ = bufrw.WriteString("Connection: Upgrade\\r\\n\\r\\n")\n\t_, _ = bufrw.WriteString("RAW_BINARY_STREAM_READY\\n")\n\t_ = bufrw.Flush()\n}\n\nfunc main() {\n\tts := httptest.NewServer(http.HandlerFunc(hijackHandler))\n\tdefer ts.Close()\n\n\tresp, err := http.Get(ts.URL)\n\tif err != nil {\n\t\tpanic(err)\n\t}\n\tdefer resp.Body.Close()\n\n\tscanner := bufio.NewScanner(resp.Body)\n\tif scanner.Scan() {\n\t\tfmt.Println("[Client received]:", scanner.Text())\n\t}\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Client received]: RAW_BINARY_STREAM_READY'}], 'under_the_hood': 'Метод `Hijack()` изолирует сокет от внутреннего пула сервера `http.Server`. Буфер `bufrw` может содержать еще не прочитанные байты от клиента, поэтому читать нужно через него, а не напрямую из `conn`.', 'pitfalls': 'В HTTP/2 протоколе `http.Hijacker` не поддерживается (попытка приведения типа вернет `false`), так как по одному TCP-соединению мультиплексируются десятки независимых HTTP/2 стримов.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему библиотека Gorilla WebSocket или Coder WebSocket требует http.Hijacker при рукопожатии (Handshake)?»\n**Ответ:** WebSocket начинается с HTTP GET запроса с заголовком `Upgrade: websocket`. Сервер подтверждает апгрейд кодом 101, после чего вызывает `Hijack()`, забирает сырой `net.Conn` и начинает обмениваться бинарными WebSocket-фреймами в полнодуплексном режиме.'}, {'num': 50, 'title': 'Автоматическое прерывание зависших хендлеров с помощью http.TimeoutHandler', 'task': 'Используйте `http.TimeoutHandler`, чтобы автоматически прерывать выполнение хендлера и отдавать 503 Service Unavailable, если он работает слишком долго.', 'theory': '`http.TimeoutHandler(h http.Handler, dt time.Duration, msg string) http.Handler` — встроенная в Go защитная обертка:\nЕсли хендлер не успевает сформировать ответ за время `dt`, клиент немедленно получает статус `503 Service Unavailable` с сообщением `msg`. Дальнейшие попытки хендлера писать в `w` вызывают ошибку `http.ErrHandlerTimeout`.', 'step_by_step': '1. Создадим долгий обработчик, эмулирующий тяжелые вычисления `time.Sleep(100ms)`.\n2. Обернем его в `http.TimeoutHandler(..., 20ms, "Превышен лимит времени")`.\n3. Отправим запрос клиентом.\n4. Убедимся в получении статуса 503.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"io"\n\t"net/http"\n\t"net/http/httptest"\n\t"time"\n)\n\nfunc slowHandler(w http.ResponseWriter, r *http.Request) {\n\t// Долгая операция\n\ttime.Sleep(50 * time.Millisecond)\n\tfmt.Fprint(w, "Успешный ответ")\n}\n\nfunc main() {\n\t// Лимит 15 мс — хендлер не успеет и получит 503\n\tprotected := http.TimeoutHandler(http.HandlerFunc(slowHandler), 15*time.Millisecond, "Сервер перегружен, попробуйте позже")\n\n\tts := httptest.NewServer(protected)\n\tdefer ts.Close()\n\n\tresp, _ := http.Get(ts.URL)\n\tbody, _ := io.ReadAll(resp.Body)\n\tresp.Body.Close()\n\n\tfmt.Printf("[Status] %d %s\\n", resp.StatusCode, resp.Status)\n\tfmt.Printf("[Body]   %s\\n", string(body))\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Status] 503 503 Service Unavailable\n# [Body]   Сервер перегружен, попробуйте позже'}], 'under_the_hood': '`TimeoutHandler` запускает исходный хендлер в отдельной горутине, а в основной ждет либо завершения, либо срабатывания таймера через `select`.', 'pitfalls': '`TimeoutHandler` прерывает ответ клиенту, но горутина внутри `slowHandler` продолжит работать до конца, если она не слушает `<-r.Context().Done()`! Для полноценной отмены всегда проверяйте контекст.', 'bigtech_interview': '**Вопрос с собеседования:** «Защищает ли http.TimeoutHandler от утечек горутин?»\n**Ответ:** Сам по себе нет. `TimeoutHandler` отдает клиенту 503 статус и закрывает канал ответа, но фоновая горутина хендлера останется висеть в памяти до тех пор, пока сама не завершится или не отреагирует на отмену `r.Context().Done()`.'}, {'num': 51, 'title': 'Middleware валидации сервисного заголовка X-API-Key с ранним прерыванием', 'task': 'Напиши middleware для проверки заголовка `X-API-Key`. Если ключ неверный или отсутствует, возвращай `http.StatusUnauthorized` (401) и прерывай цепочку (не вызывай `next`).', 'theory': 'Паттерн API-Key аутентификации широко распространен в B2B и M2M интеграциях. Ключ передается в заголовке `X-API-Key`. Если ключ отсутствует или не проходит валидацию, middleware немедленно прерывает выполнение (Short-Circuiting) без вызова `next.ServeHTTP`.', 'step_by_step': '1. Напишем `APIKeyMiddleware(validKey string, next http.Handler)`.\n2. Извлечем заголовок `r.Header.Get("X-API-Key")`.\n3. При несовпадении вернем 401 и сделаем `return`.\n4. Проверим запросы с ключом и без него.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"net/http"\n\t"net/http/httptest"\n)\n\nfunc APIKeyMiddleware(expectedKey string, next http.Handler) http.Handler {\n\treturn http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {\n\t\tapiKey := r.Header.Get("X-API-Key")\n\t\tif apiKey == "" || apiKey != expectedKey {\n\t\t\thttp.Error(w, "Доступ запрещен: отсутствует или невалидный X-API-Key", http.StatusUnauthorized)\n\t\t\treturn // Прерываем цепочку!\n\t\t}\n\t\tnext.ServeHTTP(w, r)\n\t})\n}\n\nfunc main() {\n\thandler := APIKeyMiddleware("secret-partner-key-99", http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {\n\t\tfmt.Fprint(w, "Секретные данные шлюза")\n\t}))\n\n\tts := httptest.NewServer(handler)\n\tdefer ts.Close()\n\n\t// 1. Без ключа\n\tres1, _ := http.Get(ts.URL)\n\tres1.Body.Close()\n\tfmt.Println("Без ключа статус:", res1.StatusCode)\n\n\t// 2. С валидным ключом\n\treq, _ := http.NewRequest(http.MethodGet, ts.URL, nil)\n\treq.Header.Set("X-API-Key", "secret-partner-key-99")\n\tres2, _ := http.DefaultClient.Do(req)\n\tres2.Body.Close()\n\tfmt.Println("С ключом статус: ", res2.StatusCode)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Без ключа статус: 401\n# С ключом статус:  200'}], 'under_the_hood': 'Проверка заголовка выполняется до любой дорогой бизнес-логики и работы с базой данных, экономя ресурсы CPU.', 'pitfalls': 'В проде API-ключи проверяются по кэшу Redis или мапе в памяти с хешированием (SHA-256), чтобы исключить утечку открытых ключей из БД.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему для критичных токенов сравнение проводят через crypto/subtle?»\n**Ответ:** Для предотвращения атак по сторонним каналам (Side-Channel Timing Attacks). Если злоумышленник может точно замерить время сравнения строк, он способен подобрать ключ посимвольно.'}, {'num': 52, 'title': 'Инспекция входящего Request: метод, путь, User-Agent и сетевые свойства', 'task': '**Чтение Request**: Выведи в консоль информацию о входящем запросе: `r.Method`, `r.URL.Path`, `r.UserAgent()`.', 'theory': 'Структура `http.Request` инкапсулирует полное состояние входящего HTTP-сообщения: метод запроса, путь, заголовки, параметры сокета, контекст и тело сообщения.', 'step_by_step': '1. Создадим обработчик `inspectHandler`.\n2. Извлечем и распечатаем основные свойства запроса.\n3. Отправим запрос с кастомным `User-Agent`.\n4. Проверим вывод.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"net/http"\n\t"net/http/httptest"\n)\n\nfunc inspectHandler(w http.ResponseWriter, r *http.Request) {\n\tfmt.Printf("[Request Info]\\n")\n\tfmt.Printf("  • Метод:      %s\\n", r.Method)\n\tfmt.Printf("  • Путь URL:   %s\\n", r.URL.Path)\n\tfmt.Printf("  • User-Agent: %s\\n", r.UserAgent())\n\tfmt.Printf("  • Протокол:   %s\\n", r.Proto)\n\tfmt.Printf("  • Хост:       %s\\n", r.Host)\n\tfmt.Fprint(w, "OK")\n}\n\nfunc main() {\n\tts := httptest.NewServer(http.HandlerFunc(inspectHandler))\n\tdefer ts.Close()\n\n\treq, _ := http.NewRequest(http.MethodGet, ts.URL+"/api/v1/metrics", nil)\n\treq.Header.Set("User-Agent", "PrometheusScraper/2.45")\n\n\tres, _ := http.DefaultClient.Do(req)\n\tres.Body.Close()\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Request Info]\n#   • Метод:      GET\n#   • Путь URL:   /api/v1/metrics\n#   • User-Agent: PrometheusScraper/2.45\n#   • Протокол:   HTTP/1.1\n#   • Хост:       127.0.0.1:...'}], 'under_the_hood': 'Метод `r.UserAgent()` — это удобный аксессор к `r.Header.Get("User-Agent")`.', 'pitfalls': 'Поле `r.URL.Host` на стороне сервера часто бывает пустым! Вместо него для определения запрошенного хоста всегда используйте поле `r.Host`.', 'bigtech_interview': '**Вопрос с собеседования:** «В чем разница между r.Host и r.URL.Host на стороне HTTP-сервера в Go?»\n**Ответ:** По спецификации HTTP/1.1 клиент шлет заголовок `Host: example.com`, а в строке запроса передает относительный путь `GET /index.html`. Сервер Go помещает значение заголовка в `r.Host`. Поле `r.URL.Host` заполняется только в прокси-запросах или на стороне HTTP-клиента.'}, {'num': 53, 'title': 'Reverse Proxy на httputil с Director и замером апстрим-латентности', 'task': 'Напиши **reverse proxy** (упрощённый): `httputil.ReverseProxy` с `Director`, перенаправляющий запросы на `http://localhost:9090`. Добавь логирование upstream latency.', 'theory': '`httputil.ReverseProxy` — промышленная основа обратных прокси и API-шлюзов в Go:\n1. `Director` мутирует входящий `http.Request`, переписывая схему и целевой хост бэкенда.\n2. `Transport` отправляет запрос в апстрим.\n3. `ModifyResponse` перехватывает и модифицирует ответ бэкенда перед отправкой клиенту.', 'step_by_step': '1. Создадим апстрим-сервер бэкенда (порт 9090 эмулируем через `httptest`).\n2. Сконфигурируем `httputil.ReverseProxy`.\n3. В `Director` перенаправим `req.URL` на апстрим.\n4. Замерим время ответа апстрима.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"io"\n\t"net/http"\n\t"net/http/httptest"\n\t"net/http/httputil"\n\t"net/url"\n\t"time"\n)\n\nfunc main() {\n\t// 1. Upstream Backend\n\tbackend := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {\n\t\ttime.Sleep(10 * time.Millisecond)\n\t\tw.Header().Set("X-Upstream-Server", "backend-instance-01")\n\t\tfmt.Fprint(w, "Ответ от реального бэкенда")\n\t}))\n\tdefer backend.Close()\n\n\ttargetURL, _ := url.Parse(backend.URL)\n\n\t// 2. Reverse Proxy\n\tproxy := httputil.NewSingleHostReverseProxy(targetURL)\n\toriginalDirector := proxy.Director\n\n\tproxy.Director = func(req *http.Request) {\n\t\toriginalDirector(req)\n\t\treq.Header.Set("X-Forwarded-Host", req.Header.Get("Host"))\n\t}\n\n\tproxy.ModifyResponse = func(resp *http.Response) error {\n\t\tfmt.Printf("[Proxy Monitor] Ответ от апстрима получен, статус: %d\\n", resp.StatusCode)\n\t\treturn nil\n\t}\n\n\tproxyServer := httptest.NewServer(proxy)\n\tdefer proxyServer.Close()\n\n\t// Клиент делает запрос на прокси\n\tresp, _ := http.Get(proxyServer.URL + "/catalog/items")\n\tbody, _ := io.ReadAll(resp.Body)\n\tresp.Body.Close()\n\n\tfmt.Printf("[Client Response] %s\\n", string(body))\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Proxy Monitor] Ответ от апстрима получен, статус: 200\n# [Client Response] Ответ от реального бэкенда'}], 'under_the_hood': '`httputil.ReverseProxy` автоматически удаляет Hop-by-Hop заголовки (`Connection`, `Keep-Alive`, `Proxy-Authenticate`), как того требует спецификация RFC 7230.', 'pitfalls': 'Если апстрим недоступен, прокси по умолчанию возвращает статус `502 Bad Gateway`. Обработать эту ошибку можно через поле `proxy.ErrorHandler`.', 'bigtech_interview': '**Вопрос с собеседования:** «Как ReverseProxy обрабатывает заголовок X-Forwarded-For?»\n**Ответ:** По умолчанию `httputil.ReverseProxy` автоматически добавляет IP-клиента в конец списка `X-Forwarded-For`. Если заголовка не было, он создает его со значением `r.RemoteAddr`.'}, {'num': 54, 'title': 'Архитектура потокобезопасного CRUD REST API для сущности Task', 'task': 'Спроектируйте и реализуйте CRUD REST API для сущности "Task" (создание, чтение списка, чтение по ID, обновление, удаление) с хранением в памяти (in-memory map + Mutex).', 'theory': 'Проектирование чистого слоя хранения и HTTP-контроллеров:\nРазделение ответственности:\n- Модель `Task`\n- Репозиторий `TaskRepository` с `sync.Mutex`\n- HTTP-роутер на `http.ServeMux` Go 1.22+', 'step_by_step': '1. Опишем интерфейс репозитория задач.\n2. Реализуем in-memory структуру с мьютексом.\n3. Привяжем обработчики к методам GET, POST, PUT, DELETE.\n4. Продемонстрируем полное обновление через PUT.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"bytes"\n\t"encoding/json"\n\t"fmt"\n\t"net/http"\n\t"net/http/httptest"\n\t"strconv"\n\t"sync"\n)\n\ntype Task struct {\n\tID    int    `json:"id"`\n\tTitle string `json:"title"`\n\tDone  bool   `json:"done"`\n}\n\ntype TaskRepo struct {\n\tmu    sync.Mutex\n\tdata  map[int]Task\n\tseqID int\n}\n\nfunc NewTaskRepo() *TaskRepo {\n\treturn &TaskRepo{data: make(map[int]Task), seqID: 1}\n}\n\nfunc (r *TaskRepo) Save(t Task) Task {\n\tr.mu.Lock()\n\tdefer r.mu.Unlock()\n\tt.ID = r.seqID\n\tr.seqID++\n\tr.data[t.ID] = t\n\treturn t\n}\n\nfunc (r *TaskRepo) Update(id int, title string, done bool) (Task, bool) {\n\tr.mu.Lock()\n\tdefer r.mu.Unlock()\n\tif _, exists := r.data[id]; !exists {\n\t\treturn Task{}, false\n\t}\n\tupdated := Task{ID: id, Title: title, Done: done}\n\tr.data[id] = updated\n\treturn updated, true\n}\n\nfunc main() {\n\trepo := NewTaskRepo()\n\tmux := http.NewServeMux()\n\n\tmux.HandleFunc("POST /tasks", func(w http.ResponseWriter, req *http.Request) {\n\t\tvar input struct {\n\t\t\tTitle string `json:"title"`\n\t\t}\n\t\t_ = json.NewDecoder(req.Body).Decode(&input)\n\t\tcreated := repo.Save(Task{Title: input.Title})\n\t\tw.WriteHeader(http.StatusCreated)\n\t\t_ = json.NewEncoder(w).Encode(created)\n\t})\n\n\tmux.HandleFunc("PUT /tasks/{id}", func(w http.ResponseWriter, req *http.Request) {\n\t\tid, _ := strconv.Atoi(req.PathValue("id"))\n\t\tvar input struct {\n\t\t\tTitle string `json:"title"`\n\t\t\tDone  bool   `json:"done"`\n\t\t}\n\t\t_ = json.NewDecoder(req.Body).Decode(&input)\n\t\tupdated, ok := repo.Update(id, input.Title, input.Done)\n\t\tif !ok {\n\t\t\thttp.NotFound(w, req)\n\t\t\treturn\n\t\t}\n\t\t_ = json.NewEncoder(w).Encode(updated)\n\t})\n\n\tts := httptest.NewServer(mux)\n\tdefer ts.Close()\n\n\t// 1. Создание\n\tres, _ := http.Post(ts.URL+"/tasks", "application/json", bytes.NewBufferString(`{"title":"Task 1"}`))\n\tvar created Task\n\t_ = json.NewDecoder(res.Body).Decode(&created)\n\tres.Body.Close()\n\tfmt.Printf("[POST] ID: %d, Title: %s\\n", created.ID, created.Title)\n\n\t// 2. PUT обновление\n\tputReq, _ := http.NewRequest(http.MethodPut, fmt.Sprintf("%s/tasks/%d", ts.URL, created.ID),\n\t\tbytes.NewBufferString(`{"title":"Task 1 Updated","done":true}`))\n\tputRes, _ := http.DefaultClient.Do(putReq)\n\tvar updated Task\n\t_ = json.NewDecoder(putRes.Body).Decode(&updated)\n\tputRes.Body.Close()\n\tfmt.Printf("[PUT]  ID: %d, Title: %s, Done: %v\\n", updated.ID, updated.Title, updated.Done)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [POST] ID: 1, Title: Task 1\n# [PUT]  ID: 1, Title: Task 1 Updated, Done: true'}], 'under_the_hood': 'Инкапсуляция `sync.Mutex` внутри структуры репозитория исключает доступ к мапе в обход блокировок.', 'pitfalls': 'Никогда не копируйте структуру `TaskRepo` по значению (`func (r TaskRepo)`), иначе скопируется внутреннее состояние мьютекса, что приведет к гонкам данных.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему в структурах-репозиториях мьютексы делают неэкспортируемыми (приватными)?»\n**Ответ:** Приватный мьютекс `mu sync.Mutex` гарантирует, что внешний код не сможет заблокировать его вручную или нарушить протокол синхронизации, создав дедлок.'}, {'num': 55, 'title': 'API Gateway: интеллектуальная маршрутизация микросервисов Users и Orders', 'task': 'Напиши **API Gateway** (упрощённый): маршрутизация `/users/*` → `localhost:9001`, `/orders/*` → `localhost:9002`. Используй `httputil.ReverseProxy` + `http.NewServeMux`. Добавь единый logging middleware.', 'theory': 'Паттерн API Gateway выступает единой точкой входа (Single Entry Point) для клиентов:\n- Маршрутизирует трафик на соответствующие внутренние микросервисы.\n- Скрывает топологию внутренней сети.\n- Централизует логирование, метрики и авторизацию.', 'step_by_step': '1. Запустим два бэкенда: `usersService` и `ordersService`.\n2. Создадим шлюз `gatewayMux`.\n3. Смонтируем обратные прокси на префиксы `/users/` и `/orders/`.\n4. Обернем шлюз в глобальный логгер.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"io"\n\t"net/http"\n\t"net/http/httptest"\n\t"net/http/httputil"\n\t"net/url"\n)\n\nfunc main() {\n\t// Микросервис 1: Users\n\tusersSvc := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {\n\t\tfmt.Fprintf(w, "[Users Service] Обработан путь: %s", r.URL.Path)\n\t}))\n\tdefer usersSvc.Close()\n\n\t// Микросервис 2: Orders\n\tordersSvc := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {\n\t\tfmt.Fprintf(w, "[Orders Service] Обработан путь: %s", r.URL.Path)\n\t}))\n\tdefer ordersSvc.Close()\n\n\tusersURL, _ := url.Parse(usersSvc.URL)\n\tordersURL, _ := url.Parse(ordersSvc.URL)\n\n\tgateway := http.NewServeMux()\n\tgateway.Handle("/users/", httputil.NewSingleHostReverseProxy(usersURL))\n\tgateway.Handle("/orders/", httputil.NewSingleHostReverseProxy(ordersURL))\n\n\t// Единый логирующий middleware для шлюза\n\tloggedGateway := http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {\n\t\tfmt.Printf("[API-GATEWAY] Перенаправление маршрута: %s %s\\n", r.Method, r.URL.Path)\n\t\tgateway.ServeHTTP(w, r)\n\t})\n\n\tgwServer := httptest.NewServer(loggedGateway)\n\tdefer gwServer.Close()\n\n\tres1, _ := http.Get(gwServer.URL + "/users/list")\n\tb1, _ := io.ReadAll(res1.Body)\n\tres1.Body.Close()\n\tfmt.Println(string(b1))\n\n\tres2, _ := http.Get(gwServer.URL + "/orders/active")\n\tb2, _ := io.ReadAll(res2.Body)\n\tres2.Body.Close()\n\tfmt.Println(string(b2))\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [API-GATEWAY] Перенаправление маршрута: GET /users/list\n# [Users Service] Обработан путь: /users/list\n# [API-GATEWAY] Перенаправление маршрута: GET /orders/active\n# [Orders Service] Обработан путь: /orders/active'}], 'under_the_hood': '`httputil.NewSingleHostReverseProxy` переписывает `Host` и `URL.Scheme`, направляя TCP-поток на сокет соответствующего бэкенда.', 'pitfalls': 'Если бэкенд ожидает пути без префикса `/users/`, в `proxy.Director` необходимо вызывать `http.StripPrefix` или модифицировать `req.URL.Path`.', 'bigtech_interview': '**Вопрос с собеседования:** «Каковы недостатки паттерна API Gateway и как с ними борются?»\n**Ответ:** Недостатки: единая точка отказа (SPOF) и дополнительный сетевой скачок (Latency). С этим борются горизонтальным масштабированием шлюзов через Envoy/Nginx/Go с несколькими репликами за L4-балансировщиком.'}, {'num': 56, 'title': 'Стандарты семантики HTTP-методов и обеспечение идемпотентности', 'task': 'Используйте правильные HTTP-методы и идемпотентность: `POST` для создания, `PUT` для полного обновления, `PATCH` для частичного, `DELETE` для удаления.', 'theory': 'Идемпотентность — свойство операции при повторном выполнении приводить к тому же результату, что и при однократном:\n- `GET`, `HEAD`, `OPTIONS` — безопасные (Safe) и идемпотентные.\n- `PUT`, `DELETE` — идемпотентные (повторный `DELETE` удаляет тот же объект, результат в БД одинаков).\n- `POST` — неидемпотентный (повторный запрос создает дубликаты записей).\n- `PATCH` — в общем случае неидемпотентный.', 'step_by_step': '1. Реализуем обработчик ресурса документа.\n2. Продемонстрируем разницу в поведении POST, PUT, PATCH, DELETE.\n3. Проверим идемпотентность повторного вызова DELETE.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"net/http"\n\t"net/http/httptest"\n\t"sync"\n)\n\ntype DocStore struct {\n\tmu   sync.Mutex\n\tdocs map[string]string\n}\n\nfunc main() {\n\tstore := &DocStore{docs: make(map[string]string)}\n\tmux := http.NewServeMux()\n\n\t// POST - создание нового документа (не идемпотентно)\n\tmux.HandleFunc("POST /docs", func(w http.ResponseWriter, r *http.Request) {\n\t\tw.WriteHeader(http.StatusCreated)\n\t\tfmt.Fprint(w, "Doc created")\n\t})\n\n\t// PUT - полная замена (идемпотентно)\n\tmux.HandleFunc("PUT /docs/{id}", func(w http.ResponseWriter, r *http.Request) {\n\t\tid := r.PathValue("id")\n\t\tstore.mu.Lock()\n\t\tstore.docs[id] = "full replacement"\n\t\tstore.mu.Unlock()\n\t\tw.WriteHeader(http.StatusOK)\n\t\tfmt.Fprint(w, "Doc replaced")\n\t})\n\n\t// DELETE - удаление (идемпотентно)\n\tmux.HandleFunc("DELETE /docs/{id}", func(w http.ResponseWriter, r *http.Request) {\n\t\tid := r.PathValue("id")\n\t\tstore.mu.Lock()\n\t\tdelete(store.docs, id)\n\t\tstore.mu.Unlock()\n\t\tw.WriteHeader(http.StatusNoContent)\n\t})\n\n\tts := httptest.NewServer(mux)\n\tdefer ts.Close()\n\n\t// Проверяем идемпотентность DELETE (повторные вызовы возвращают 204)\n\treq1, _ := http.NewRequest(http.MethodDelete, ts.URL+"/docs/doc1", nil)\n\tr1, _ := http.DefaultClient.Do(req1)\n\tr1.Body.Close()\n\n\treq2, _ := http.NewRequest(http.MethodDelete, ts.URL+"/docs/doc1", nil)\n\tr2, _ := http.DefaultClient.Do(req2)\n\tr2.Body.Close()\n\n\tfmt.Printf("DELETE #1 Status: %d\\n", r1.StatusCode)\n\tfmt.Printf("DELETE #2 Status: %d (Идемпотентно!)\\n", r2.StatusCode)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# DELETE #1 Status: 204\n# DELETE #2 Status: 204 (Идемпотентно!)'}], 'under_the_hood': 'Спецификация HTTP/1.1 (RFC 7231) гарантирует клиентам, что идемпотентные методы можно безопасно повторять при сетевых таймаутах.', 'pitfalls': 'Если в DELETE возвращать 404 при повторном вызове, метод формально теряет статус-код идемпотентности для тупых клиентов, хотя состояние базы данных остается тем же.', 'bigtech_interview': '**Вопрос с собеседования:** «Как сделать POST-запрос платежа идемпотентным?»\n**Ответ:** Использовать заголовок `Idempotency-Key` (UUID). Сервер перед списанием средств сохраняет ключ в Redis со статусом `IN_PROGRESS`. При повторном запросе с тем же ключом сервер возвращает сохраненный результат предыдущей транзакции без повторного списания денег.'}, {'num': 57, 'title': 'Надежный RecoverPanic Middleware с безопасным возвратом 500 клиенту', 'task': 'Напиши middleware `RecoverPanic`, который использует `defer` и `recover()`. Если внутри обработчика возникает паника, перехвати её, верни клиенту `500 Internal Server Error` и не урони сервер.', 'theory': 'Неперехваченная паника в бизнес-логике обрывает TCP-сокет. Корректный Recovery Middleware обязан перехватить панику, залогировать стек и сформировать валидный HTTP-ответ с кодом 500.', 'step_by_step': '1. Создадим `RecoverPanic(next http.Handler) http.Handler`.\n2. В блоке `defer` вызовем `recover()`.\n3. Если паника была, запишем ответ `500 Internal Server Error`.\n4. Проверим сохранение работоспособности сервера.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"io"\n\t"net/http"\n\t"net/http/httptest"\n)\n\nfunc RecoverPanic(next http.Handler) http.Handler {\n\treturn http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {\n\t\tdefer func() {\n\t\t\tif rErr := recover(); rErr != nil {\n\t\t\t\tfmt.Printf("[PANIC CAUGHT]: %v\\n", rErr)\n\t\t\t\tw.Header().Set("Connection", "close")\n\t\t\t\thttp.Error(w, `{"error":"500 Internal Server Error"}`, http.StatusInternalServerError)\n\t\t\t}\n\t\t}()\n\t\tnext.ServeHTTP(w, r)\n\t})\n}\n\nfunc main() {\n\tmux := http.NewServeMux()\n\tmux.HandleFunc("/crash", func(w http.ResponseWriter, r *http.Request) {\n\t\tpanic("critical business error: divide by zero")\n\t})\n\n\tts := httptest.NewServer(RecoverPanic(mux))\n\tdefer ts.Close()\n\n\tresp, _ := http.Get(ts.URL + "/crash")\n\tbody, _ := io.ReadAll(resp.Body)\n\tresp.Body.Close()\n\n\tfmt.Printf("Код ответа: %d\\n", resp.StatusCode)\n\tfmt.Printf("Тело ответа: %s\\n", string(body))\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [PANIC CAUGHT]: critical business error: divide by zero\n# Код ответа: 500\n# Тело ответа: {"error":"500 Internal Server Error"}'}], 'under_the_hood': 'Заголовок `Connection: close` указывает клиенту закрыть соединение, так как после паники внутреннее состояние сокета может быть повреждено.', 'pitfalls': 'Если паника произошла уже ПОСЛЕ того, как часть ответа была отправлена клиенту в сокет, изменить статус-код на 500 уже невозможно.', 'bigtech_interview': '**Вопрос с собеседования:** «Что происходит с соединением, если паника перехвачена после частичной записи в ResponseWriter?»\n**Ответ:** Соединение оказывается в поврежденном полузаписанном состоянии. Сервер обязан разорвать TCP-сокет, чтобы клиент не получил усеченные или склеенные данные следующего запроса.'}, {'num': 58, 'title': 'Асинхронный стриминг без временных файлов с использованием io.Pipe', 'task': "Напиши **HTTP handler с `io.Pipe`**: создай `pr, pw := io.Pipe()`. Запусти горутину, которая пишет в `pw` (генерирует данные). В handler'е читай из `pr` и копируй в `http.ResponseWriter`. Покажи streaming без временных файлов.", 'theory': '`io.Pipe()` связывает синхронный `io.Reader` и `io.Writer` в оперативной памяти без буферизации на диск:\nГорутина-генератор пишет в `pw`, а HTTP-хендлер параллельно вычитывает из `pr` и отправляет клиенту через `io.Copy(w, pr)`. При завершении записи горутина обязана закрыть `pw.Close()`.', 'step_by_step': '1. Создадим пайп: `pr, pw := io.Pipe()`.\n2. В отдельной горутине сгенерируем CSV-отчет и запишем в `pw`.\n3. В главной горутине вызовем `io.Copy(w, pr)`.\n4. Проверим получение стрима клиентом.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"io"\n\t"net/http"\n\t"net/http/httptest"\n\t"time"\n)\n\nfunc pipeStreamingHandler(w http.ResponseWriter, r *http.Request) {\n\tpr, pw := io.Pipe()\n\n\t// Фоновый генератор отчета\n\tgo func() {\n\t\tdefer pw.Close()\n\t\tfor i := 1; i <= 3; i++ {\n\t\t\tline := fmt.Sprintf("id_%d,metric_value_%d\\n", i, i*100)\n\t\t\t_, _ = pw.Write([]byte(line))\n\t\t\ttime.Sleep(10 * time.Millisecond) // Эмуляция вычислений\n\t\t}\n\t}()\n\n\tw.Header().Set("Content-Type", "text/csv")\n\tw.Header().Set("Transfer-Encoding", "chunked")\n\n\t// Потоковая перекачка из пайпа в сокет клиента\n\t_, _ = io.Copy(w, pr)\n}\n\nfunc main() {\n\tts := httptest.NewServer(http.HandlerFunc(pipeStreamingHandler))\n\tdefer ts.Close()\n\n\tresp, _ := http.Get(ts.URL)\n\tbody, _ := io.ReadAll(resp.Body)\n\tresp.Body.Close()\n\n\tfmt.Print(string(body))\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# id_1,metric_value_100\n# id_2,metric_value_200\n# id_3,metric_value_300'}], 'under_the_hood': '`io.Pipe` блокирует пишущую горутину до тех пор, пока читающая горутина не вычитает байты. Это обеспечивает автоматический Backpressure (обратное давление) без переполнения RAM.', 'pitfalls': 'Если забыть вызвать `pw.Close()`, читающая сторона в `io.Copy` зависнет навсегда в ожидании `EOF`.', 'bigtech_interview': '**Вопрос с собеседования:** «Как io.Pipe обеспечивает Backpressure при формировании больших отчетов?»\n**Ответ:** Каждый вызов `pw.Write()` блокируется до момента, пока читатель `pr.Read()` не заберет порцию данных. Если клиент читает медленно по медленной сети, генератор данных автоматически притормаживает и не забивает оперативную память сервера.'}, {'num': 59, 'title': 'Ловушка Partial Write: почему ошибки нужно проверять строго до первой записи', 'task': 'Напиши **HTTP handler с ошибкой и partial write**: handler пишет заголовок `200`, затем часть тела, затем паникует. Покажи, что `http.ResponseWriter` не позволяет изменить статус после первого `Write`. Обсуди, почему важно проверять ошибки до первого Write.', 'theory': 'В протоколе HTTP статусная строка передается в самом первом TCP-пакете. Как только выполнена первая запись `w.Write()`, статус `200 OK` уже отправлен клиенту. Если в середине формирования ответа произойдет ошибка, сервер не сможет вернуть 500 — соединение просто аварийно оборвется, оставив клиента с поврежденным файлом.', 'step_by_step': '1. Создадим обработчик с частичной записью.\n2. Отправим часть ответа.\n3. Продемонстрируем возникновение ошибки на середине передачи.\n4. Проверим статус 200 у поврежденного ответа.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"io"\n\t"net/http"\n\t"net/http/httptest"\n)\n\nfunc partialWriteHandler(w http.ResponseWriter, r *http.Request) {\n\t// 1. Отправляем 200 OK и первую часть данных\n\tw.WriteHeader(http.StatusOK)\n\t_, _ = w.Write([]byte(`{"items": [1, 2, `)) // Заголовок ушел!\n\n\t// 2. Внезапный сбой в середине генерации (например, отвалилась БД)\n\tdbError := true\n\tif dbError {\n\t\t// Попытка изменить статус на 500 ни к чему не приведет!\n\t\t// w.WriteHeader(http.StatusInternalServerError) // superfluous warning\n\t\t_, _ = w.Write([]byte(`"ERROR: DB Connection Lost"}`))\n\t\treturn\n\t}\n}\n\nfunc main() {\n\tts := httptest.NewServer(http.HandlerFunc(partialWriteHandler))\n\tdefer ts.Close()\n\n\tresp, _ := http.Get(ts.URL)\n\tbody, _ := io.ReadAll(resp.Body)\n\tresp.Body.Close()\n\n\tfmt.Printf("Полученный статус: %d (Хотя произошла ошибка!)\\n", resp.StatusCode)\n\tfmt.Printf("Поврежденное тело: %s\\n", string(body))\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Полученный статус: 200 (Хотя произошла ошибка!)\n# Поврежденное тело: {"items": [1, 2, "ERROR: DB Connection Lost"}'}], 'under_the_hood': 'Статус-код и заголовки фиксируются при первом обращении к сокету. Изменить их задним числом физически невозможно в протоколах HTTP/1.1 и HTTP/2.', 'pitfalls': 'Если формировать JSON в `w` по частям без предварительной валидации всех данных, клиент распарсит невалидный JSON и упадет.', 'bigtech_interview': '**Вопрос с собеседования:** «Как предотвратить проблему Partial Write при генерации тяжелых JSON ответов?»\n**Ответ:** Либо полностью сформировать и сериализовать данные в памяти / буфере (`bytes.Buffer`) до отправки в `w` (если ответ помещается в RAM), либо использовать протоколы с поддержкой трейлеров (HTTP Trailers) и потоковой обработки ошибок (gRPC status codes в конце стрима).'}, {'num': 60, 'title': 'Полнофункциональная пагинация с limit, offset и расчетом total_pages', 'task': 'Реализуйте пагинацию в методе `GET /tasks`, принимая параметры `limit` и `offset` (или `cursor`), и отдавайте метаданные о общем количестве страниц.', 'theory': 'Промышленный стандарт постраничного вывода (Offset-based Pagination):\n- `limit` — количество запрашиваемых записей на страницу.\n- `offset` — смещение от начала списка.\n- `total` — общее число записей.\n- `total_pages = (total + limit - 1) / limit` (целочисленное округление вверх).', 'step_by_step': '1. Создадим обработчик `GET /tasks`.\n2. Извлечем и валидируем `limit` и `offset`.\n3. Вычислим срез элементов и общее количество страниц.\n4. Вернем структурированный ответ с метаданными.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"encoding/json"\n\t"fmt"\n\t"io"\n\t"net/http"\n\t"net/http/httptest"\n\t"strconv"\n)\n\ntype TaskItem struct {\n\tID    int    `json:"id"`\n\tTitle string `json:"title"`\n}\n\ntype PagedResponse struct {\n\tLimit      int        `json:"limit"`\n\tOffset     int        `json:"offset"`\n\tTotal      int        `json:"total"`\n\tTotalPages int        `json:"total_pages"`\n\tItems      []TaskItem `json:"items"`\n}\n\nfunc main() {\n\tvar allTasks []TaskItem\n\tfor i := 1; i <= 25; i++ {\n\t\tallTasks = append(allTasks, TaskItem{ID: i, Title: fmt.Sprintf("Задача #%d", i)})\n\t}\n\n\tmux := http.NewServeMux()\n\tmux.HandleFunc("GET /tasks", func(w http.ResponseWriter, r *http.Request) {\n\t\tlimit, _ := strconv.Atoi(r.URL.Query().Get("limit"))\n\t\tif limit <= 0 || limit > 100 {\n\t\t\tlimit = 10\n\t\t}\n\t\toffset, _ := strconv.Atoi(r.URL.Query().Get("offset"))\n\t\tif offset < 0 {\n\t\t\toffset = 0\n\t\t}\n\n\t\ttotal := len(allTasks)\n\t\tstart := offset\n\t\tif start > total {\n\t\t\tstart = total\n\t\t}\n\t\tend := start + limit\n\t\tif end > total {\n\t\t\tend = total\n\t\t}\n\n\t\ttotalPages := (total + limit - 1) / limit\n\n\t\tresp := PagedResponse{\n\t\t\tLimit:      limit,\n\t\t\tOffset:     offset,\n\t\t\tTotal:      total,\n\t\t\tTotalPages: totalPages,\n\t\t\tItems:      allTasks[start:end],\n\t\t}\n\n\t\tw.Header().Set("Content-Type", "application/json")\n\t\t_ = json.NewEncoder(w).Encode(resp)\n\t})\n\n\tts := httptest.NewServer(mux)\n\tdefer ts.Close()\n\n\tres, _ := http.Get(ts.URL + "/tasks?limit=5&offset=10")\n\tbody, _ := io.ReadAll(res.Body)\n\tres.Body.Close()\n\n\tfmt.Println(string(body))\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# {"items":[{"id":11,"title":"Задача #11"},{"id":12,"title":"Задача #12"},{"id":13,"title":"Задача #13"},{"id":14,"title":"Задача #14"},{"id":15,"title":"Задача #15"}],"limit":5,"offset":10,"total":25,"total_pages":5}'}], 'under_the_hood': 'Формула `(total + limit - 1) / limit` в целочисленной арифметике Go заменяет медленный `math.Ceil(float64(total)/float64(limit))` без конвертации в числа с плавающей точкой.', 'pitfalls': 'При динамическом добавлении данных в БД между запросами клиент при постраничной пагинации по offset может увидеть дублирование элементов. Для лент новостей используют Cursor Pagination.', 'bigtech_interview': '**Вопрос с собеседования:** «В чем преимущество формулы `(total + limit - 1) / limit` над `math.Ceil`?»\n**Ответ:** Целочисленная формула выполняется за 1 инструкцию процессора без переключения регистров FPU и риска потери точности на больших 64-битных числах.'}, {'num': 61, 'title': 'Многослойный защитный пайплайн: Recovery, Auth и Logging Middleware', 'task': 'Цепочка middleware: оберните обработчик в middleware логирования, аутентификации и восстановления после паники.', 'theory': 'Каноническая трехуровневая архитектура защиты HTTP-эндпоинтов в Go:\n1. `RecoveryMiddleware` (самый внешний уровень) — перехватывает паники, предотвращая обрыв сокетов.\n2. `LoggingMiddleware` — фиксирует метрики каждого запроса (включая перехваченные паники со статусом 500).\n3. `AuthMiddleware` — проверяет права доступа до вызова бизнес-логики.\n4. `Handler` — целевой обработчик запроса.', 'step_by_step': '1. Реализуем три middleware: `Recovery`, `Logging`, `Auth`.\n2. Соберем стек: `Recovery(Logging(Auth(handler)))`.\n3. Протестируем успешный запрос.\n4. Протестируем паникующий запрос и убедимся, что она залогирована и клиенту отдан код 500.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"net/http"\n\t"net/http/httptest"\n)\n\nfunc RecoveryMW(next http.Handler) http.Handler {\n\treturn http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {\n\t\tdefer func() {\n\t\t\tif rec := recover(); rec != nil {\n\t\t\t\thttp.Error(w, "Внутренняя ошибка сервера", http.StatusInternalServerError)\n\t\t\t}\n\t\t}()\n\t\tnext.ServeHTTP(w, r)\n\t})\n}\n\nfunc LoggingMW(next http.Handler) http.Handler {\n\treturn http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {\n\t\tfmt.Printf("[LOG] Запрос %s %s\\n", r.Method, r.URL.Path)\n\t\tnext.ServeHTTP(w, r)\n\t})\n}\n\nfunc AuthMW(next http.Handler) http.Handler {\n\treturn http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {\n\t\tif r.Header.Get("X-User") == "" {\n\t\t\thttp.Error(w, "Требуется авторизация", http.StatusUnauthorized)\n\t\t\treturn\n\t\t}\n\t\tnext.ServeHTTP(w, r)\n\t})\n}\n\nfunc main() {\n\thandler := http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {\n\t\tfmt.Fprint(w, "Добро пожаловать в защищенную зону")\n\t})\n\n\tpipeline := RecoveryMW(LoggingMW(AuthMW(handler)))\n\tts := httptest.NewServer(pipeline)\n\tdefer ts.Close()\n\n\t// Запрос с заголовком\n\treq, _ := http.NewRequest(http.MethodGet, ts.URL, nil)\n\treq.Header.Set("X-User", "alex")\n\tres, _ := http.DefaultClient.Do(req)\n\tres.Body.Close()\n\n\tfmt.Println("Статус ответа:", res.StatusCode)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [LOG] Запрос GET /\n# Статус ответа: 200'}], 'under_the_hood': 'Стек вызовов вложенных функций разворачивается LIFO (Last In, First Out). `RecoveryMW` первым встречает входящий запрос и последним ловит вылетающие паники.', 'pitfalls': 'Если поместить `RecoveryMW` внутрь `LoggingMW`, то при панике в `AuthMW` или `Handler` внешнее логирование может не зафиксировать статус ответа 500.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему в цепочке Middleware важен строгий порядок регистрации?»\n**Ответ:** Неправильный порядок нарушает контракт безопасности: например, если поместить `RateLimiting` после `Auth`, злоумышленник сможет устроить DoS дорогой базой данных паролей до срабатывания ограничений частоты запросов.'}, {'num': 62, 'title': 'Парсинг JSON-тела с обработкой ошибок десериализации и статусом 400', 'task': '**Парсинг JSON-тела**: Напиши роут `POST /users`. Внутри используй `json.NewDecoder(r.Body).Decode(&user)`. Верни клиенту статус 400 (`http.Error`), если JSON оказался невалидным.', 'theory': 'Прием JSON-запросов требует обязательной проверки возвращаемой ошибки `err := json.NewDecoder(r.Body).Decode(&dst)`. Возможные типы ошибок:\n- `*json.SyntaxError` — синтаксическая ошибка в JSON.\n- `io.EOF` — пустое тело запроса.\n- `*json.UnmarshalTypeError` — несоответствие типов (например, строка вместо числа).', 'step_by_step': '1. Создадим обработчик `POST /users`.\n2. Ограничим размер входного потока `http.MaxBytesReader`.\n3. Распарсим тело в структуру `User`.\n4. Вернем 400 Bad Request при любой ошибке.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"bytes"\n\t"encoding/json"\n\t"fmt"\n\t"io"\n\t"net/http"\n\t"net/http/httptest"\n)\n\ntype UserPayload struct {\n\tName  string `json:"name"`\n\tScore int    `json:"score"`\n}\n\nfunc createUser(w http.ResponseWriter, r *http.Request) {\n\tdefer r.Body.Close()\n\n\tvar u UserPayload\n\tif err := json.NewDecoder(r.Body).Decode(&u); err != nil {\n\t\thttp.Error(w, fmt.Sprintf("Невалидный JSON: %v", err), http.StatusBadRequest)\n\t\treturn\n\t}\n\n\tw.WriteHeader(http.StatusCreated)\n\tfmt.Fprintf(w, "Пользователь %s зарегистрирован со счетом %d", u.Name, u.Score)\n}\n\nfunc main() {\n\tmux := http.NewServeMux()\n\tmux.HandleFunc("POST /users", createUser)\n\n\tts := httptest.NewServer(mux)\n\tdefer ts.Close()\n\n\t// Отправляем поврежденный JSON\n\tinvalidJSON := `{"name": "test", score: "not-a-number"}`\n\tres, _ := http.Post(ts.URL+"/users", "application/json", bytes.NewBufferString(invalidJSON))\n\tbody, _ := io.ReadAll(res.Body)\n\tres.Body.Close()\n\n\tfmt.Printf("[Status] %d\\n", res.StatusCode)\n\tfmt.Printf("[Error]  %s", string(body))\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': "go run main.go\n# Вывод:\n# [Status] 400\n# [Error]  Невалидный JSON: invalid character 's' looking for beginning of object key string"}], 'under_the_hood': '`json.NewDecoder` читает входной поток побайтово через лексер без предварительной вычитки всего содержимого в память.', 'pitfalls': 'Если в теле запроса передано два валидных JSON подряд (`{"a":1}{"b":2}`), одиночный `Decode` прочитает только первый и завершится без ошибки, проигнорировав «хвост».', 'bigtech_interview': '**Вопрос с собеседования:** «Как проверить, что в теле запроса содержится ровно один JSON-объект без лишнего мусора в конце?»\n**Ответ:** После первого вызова `dec.Decode(&dst)` вызвать `dec.Decode(&struct{}{})` и убедиться, что второй вызов возвращает строго ошибку `io.EOF`.'}, {'num': 63, 'title': 'Реализация вспомогательной функции-компоновщика Middleware Chain', 'task': 'Создай цепочку из трех middleware (Логирование -> Авторизация -> Сам обработчик). Напиши функцию-помощник для их объединения.', 'theory': 'Для устранения глубокой вложенности вызовов (`M1(M2(M3(handler)))`) создают функцию-компоновщик `Chain(handlers ...Middleware) Middleware`, которая последовательно связывает слои в цикле справа налево.', 'step_by_step': '1. Объявим тип `type Middleware func(http.Handler) http.Handler`.\n2. Реализуем хелпер `CreateChain(mws ...Middleware) Middleware`.\n3. Соберем цепочку из трех компонентов.\n4. Проверим аккуратный декларативный синтаксис.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"net/http"\n\t"net/http/httptest"\n)\n\ntype Middleware func(http.Handler) http.Handler\n\nfunc Chain(mws ...Middleware) Middleware {\n\treturn func(final http.Handler) http.Handler {\n\t\tfor i := len(mws) - 1; i >= 0; i-- {\n\t\t\tfinal = mws[i](final)\n\t\t}\n\t\treturn final\n\t}\n}\n\nfunc Logger(next http.Handler) http.Handler {\n\treturn http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {\n\t\tfmt.Println("[Step 1] Logger executed")\n\t\tnext.ServeHTTP(w, r)\n\t})\n}\n\nfunc Authenticator(next http.Handler) http.Handler {\n\treturn http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {\n\t\tfmt.Println("[Step 2] Authenticator executed")\n\t\tnext.ServeHTTP(w, r)\n\t})\n}\n\nfunc Tracer(next http.Handler) http.Handler {\n\treturn http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {\n\t\tfmt.Println("[Step 3] Tracer executed")\n\t\tnext.ServeHTTP(w, r)\n\t})\n}\n\nfunc main() {\n\tcoreHandler := http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {\n\t\tfmt.Fprint(w, "Core logic")\n\t})\n\n\t// Элегантная сборка без вложенных скобок\n\tstack := Chain(Logger, Authenticator, Tracer)\n\n\tts := httptest.NewServer(stack(coreHandler))\n\tdefer ts.Close()\n\n\tres, _ := http.Get(ts.URL)\n\tres.Body.Close()\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Step 1] Logger executed\n# [Step 2] Authenticator executed\n# [Step 3] Tracer executed'}], 'under_the_hood': 'Итерация в обратном порядке `len(mws)-1 down to 0` гарантирует, что первое указанное в списке middleware будет вызвано первым при поступлении запроса.', 'pitfalls': 'Если развернуть цикл слева направо без реверса, порядок выполнения инвертируется, что сломает логику авторизации.', 'bigtech_interview': '**Вопрос с собеседования:** «Чем самописный Chain отличается от популярной библиотеки justinas/alice?»\n**Ответ:** По сути `justinas/alice` реализует ровно этот же паттерн сворачивания (fold right) среза `[]Constructor`, добавляя методы `Append` и `Extend` для удобного объединения наборов middleware.'}, {'num': 64, 'title': 'Реакция на закрытие вкладки: прерывание тяжелых запросов через r.Context().Done()', 'task': 'Интегрируйте `context` во все хендлеры. Если клиент отменил запрос (закрыл вкладку), ваш хендлер должен заметить `<-ctx.Done()` и прервать тяжелый запрос к "БД" (эмулируйте долгий `time.Sleep`).', 'theory': 'При разрыве клиентского TCP-соединения (закрытие вкладки браузера, `curl` прерван по Ctrl+C) HTTP-сервер Go автоматически отменяет контекст запроса `r.Context()`. Обработчик обязан опрашивать `<-r.Context().Done()`, чтобы своевременно освободить соединения с БД и сэкономить такты CPU.', 'step_by_step': '1. Создадим тяжелый обработчик, работающий в цикле.\n2. На каждой итерации проверим `select` с веткой `case <-r.Context().Done()`.\n3. Запустим клиент и принудительно оборвем запрос через таймаут.\n4. Убедимся, что хендлер зафиксировал отмену и вышел.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"context"\n\t"fmt"\n\t"net/http"\n\t"net/http/httptest"\n\t"time"\n)\n\nfunc heavyDatabaseHandler(w http.ResponseWriter, r *http.Request) {\n\tctx := r.Context()\n\tfmt.Println("[Server] Начало выполнения тяжелой аналитической выборки...")\n\n\tselect {\n\tcase <-time.After(200 * time.Millisecond): // Эмуляция работы\n\t\tfmt.Fprint(w, "Результаты аналитики")\n\t\tfmt.Println("[Server] Запрос успешно выполнен")\n\tcase <-ctx.Done(): // Клиент отключился!\n\t\tfmt.Printf("[Server] КЛИЕНТ ОТМЕНИЛ ЗАПРОС! Причина: %v. Прерываем транзакцию!\\n", ctx.Err())\n\t\treturn\n\t}\n}\n\nfunc main() {\n\tts := httptest.NewServer(http.HandlerFunc(heavyDatabaseHandler))\n\tdefer ts.Close()\n\n\t// Клиент с коротким таймаутом (эмулирует закрытие вкладки)\n\tctx, cancel := context.WithTimeout(context.Background(), 50*time.Millisecond)\n\tdefer cancel()\n\n\treq, _ := http.NewRequestWithContext(ctx, http.MethodGet, ts.URL, nil)\n\t_, _ = http.DefaultClient.Do(req)\n\n\ttime.Sleep(100 * time.Millisecond) // Ждем завершения сервера\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Server] Начало выполнения тяжелой аналитической выборки...\n# [Server] КЛИЕНТ ОТМЕНИЛ ЗАПРОС! Причина: context canceled. Прерываем транзакцию!'}], 'under_the_hood': 'Рантайм `net/http` отслеживает события `epoll` на сокете клиента. Как только от клиента приходит TCP FIN или RST, сервер вызывает внутренний `cancel()` для контекста запроса.', 'pitfalls': 'Передача `context.Background()` в вызовы `db.QueryContext` вместо `r.Context()` лишает сервис защиты от бесполезных вычислений при отключении клиентов.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему в микросервисах на Go критично пробрасывать r.Context() во все нижележащие RPC и SQL вызовы?»\n**Ответ:** Это реализует сквозную отмену (Cascading Cancellation). Если пользователь закрыл мобильное приложение, отмена запроса на Gateway мгновенно распространяется по цепочке на все внутренние микросервисы и БД, экономя колоссальное количество ресурсов кластера.'}, {'num': 65, 'title': 'Перехват системного сигнала os.Interrupt для Graceful Shutdown HTTP-сервера', 'task': '**Graceful Shutdown**: Напишите сервер, который перехватывает сигнал ОС (`os.Interrupt`), перестает принимать новые подключения (`server.Shutdown(ctx)`) и ждет завершения текущих активных запросов.', 'theory': 'При получении `os.Interrupt` (SIGINT / Ctrl+C) или `syscall.SIGTERM` сервер не должен немедленно завершаться через `os.Exit(0)`. Необходимо вызвать `server.Shutdown(ctx)` с таймаутом, чтобы все текущие запросы успели завершиться.', 'step_by_step': '1. Создадим канал сигналов `sigChan := make(chan os.Signal, 1)`.\n2. Подпишемся на `signal.Notify(sigChan, os.Interrupt)`.\n3. Запустим сервер в фоновой горутине.\n4. При сигнале вызовем `srv.Shutdown(ctx)`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"context"\n\t"fmt"\n\t"net/http"\n\t"os"\n\t"time"\n)\n\nfunc main() {\n\tmux := http.NewServeMux()\n\tmux.HandleFunc("/work", func(w http.ResponseWriter, r *http.Request) {\n\t\ttime.Sleep(30 * time.Millisecond)\n\t\tfmt.Fprint(w, "Готово")\n\t})\n\n\tsrv := &http.Server{\n\t\tAddr:    "127.0.0.1:9011",\n\t\tHandler: mux,\n\t}\n\n\tgo func() {\n\t\t_ = srv.ListenAndServe()\n\t}()\n\n\t// Канал для сигналов\n\tstop := make(chan os.Signal, 1)\n\t// Имитируем отправку прерывания через 40 мс\n\tgo func() {\n\t\ttime.Sleep(40 * time.Millisecond)\n\t\tstop <- os.Interrupt\n\t}()\n\n\t<-stop\n\tfmt.Println("[Shutdown] Получен сигнал остановки, останавливаем прием новых запросов...")\n\n\tctx, cancel := context.WithTimeout(context.Background(), 2*time.Second)\n\tdefer cancel()\n\n\tif err := srv.Shutdown(ctx); err != nil {\n\t\tfmt.Printf("Ошибка остановки: %v\\n", err)\n\t} else {\n\t\tfmt.Println("[Shutdown] Сервер плавно остановлен!")\n\t}\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Shutdown] Получен сигнал остановки, останавливаем прием новых запросов...\n# [Shutdown] Сервер плавно остановлен!'}], 'under_the_hood': 'Канал сигналов `make(chan os.Signal, 1)` обязан иметь размер буфера не менее 1, чтобы не потерять сигнал, если горутина не успела встать на чтение.', 'pitfalls': 'Никогда не используйте небуферизированный канал `make(chan os.Signal)` для сигналов операционной системы.', 'bigtech_interview': '**Вопрос с собеседования:** «Что произойдет, если в Shutdown истечет контекст с таймаутом?»\n**Ответ:** `srv.Shutdown` вернет ошибку `context.DeadlineExceeded` и принудительно закроет все оставшиеся зависшие TCP-соединения, позволив процессу корректно завершиться.'}, {'num': 66, 'title': 'Мягкая остановка при SIGINT с дожиданием активных соединений', 'task': 'Создайте сервер, который поддерживает Graceful Shutdown: при получении `SIGINT` он завершает приём новых запросов, дожидается выполнения текущих и завершает работу.', 'theory': 'Синхронизация фоновых горутин сервиса и HTTP-сервера с помощью `sync.WaitGroup` гарантирует, что программа не выйдет до полной обработки текущих запросов.', 'step_by_step': '1. Создадим счетчик `sync.WaitGroup`.\n2. Запустим сервер и фоновую задачу.\n3. Дождемся завершения вызова `srv.Shutdown`.\n4. Зафиксируем чистое завершение процесса.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"context"\n\t"fmt"\n\t"net/http"\n\t"time"\n)\n\nfunc main() {\n\tserver := &http.Server{\n\t\tAddr: "127.0.0.1:9012",\n\t\tHandler: http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {\n\t\t\ttime.Sleep(20 * time.Millisecond)\n\t\t\tfmt.Fprint(w, "OK")\n\t\t}),\n\t}\n\n\tgo func() {\n\t\t_ = server.ListenAndServe()\n\t}()\n\n\ttime.Sleep(10 * time.Millisecond)\n\n\t// Запускаем фоновый запрос\n\tgo func() {\n\t\tres, err := http.Get("http://127.0.0.1:9012/")\n\t\tif err == nil {\n\t\t\tres.Body.Close()\n\t\t\tfmt.Println("[Client] Запрос успел завершиться до полной остановки")\n\t\t}\n\t}()\n\n\ttime.Sleep(5 * time.Millisecond)\n\n\t// Остановка сервера\n\tctx, cancel := context.WithTimeout(context.Background(), 1*time.Second)\n\tdefer cancel()\n\n\t_ = server.Shutdown(ctx)\n\tfmt.Println("[Server] Остановлен без потери запросов")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Client] Запрос успел завершиться до полной остановки\n# [Server] Остановлен без потери запросов'}], 'under_the_hood': '`server.Shutdown()` переводит внутреннее состояние сервера в режим `shuttingDown`, при котором вызовы `Accept()` немедленно отклоняются.', 'pitfalls': 'Если после `Shutdown()` забыть завершить соединение с базой данных `db.Close()`, транзакции могут остаться незафиксированными.', 'bigtech_interview': '**Вопрос с собеседования:** «В каком порядке закрывать ресурсы в main при Graceful Shutdown?»\n**Ответ:** В обратном порядке инициализации: сначала `server.Shutdown(ctx)` (прекращаем входящий трафик и ждем запросы), затем очереди сообщений (RabbitMQ/Kafka consumer), затем кэш и соединения с базой данных `db.Close()`.'}, {'num': 67, 'title': 'Формирование JSON-ответов со строгим порядком установки заголовков и статуса 201', 'task': '**Отправка JSON-ответа**: Верни клиенту структуру в виде JSON. Обязательно установи заголовок `w.Header().Set("Content-Type", "application/json")`, статус `w.WriteHeader(http.StatusCreated)` и только потом пиши тело (через `json.NewEncoder`).', 'theory': 'Стандартный порядок формирования ответа в REST API:\n1. `w.Header().Set("Content-Type", "application/json")`\n2. `w.WriteHeader(code)`\n3. `json.NewEncoder(w).Encode(data)`', 'step_by_step': '1. Создадим обработчик `createItem`.\n2. Соблюдем правильную последовательность шагов.\n3. Отправим проверочный запрос.\n4. Проверим статус и заголовок `Content-Type`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"encoding/json"\n\t"fmt"\n\t"net/http"\n\t"net/http/httptest"\n)\n\ntype CreatedResponse struct {\n\tID      int    `json:"id"`\n\tMessage string `json:"message"`\n}\n\nfunc createItemHandler(w http.ResponseWriter, r *http.Request) {\n\t// Шаг 1: Заголовки\n\tw.Header().Set("Content-Type", "application/json")\n\t// Шаг 2: Статус\n\tw.WriteHeader(http.StatusCreated)\n\t// Шаг 3: Тело\n\t_ = json.NewEncoder(w).Encode(CreatedResponse{\n\t\tID:      777,\n\t\tMessage: "Объект успешно создан",\n\t})\n}\n\nfunc main() {\n\tts := httptest.NewServer(http.HandlerFunc(createItemHandler))\n\tdefer ts.Close()\n\n\tres, _ := http.Get(ts.URL)\n\tdefer res.Body.Close()\n\n\tvar resp CreatedResponse\n\t_ = json.NewDecoder(res.Body).Decode(&resp)\n\n\tfmt.Printf("[Status]       %d\\n", res.StatusCode)\n\tfmt.Printf("[Content-Type] %s\\n", res.Header.Get("Content-Type"))\n\tfmt.Printf("[Response]     ID=%d, Msg=%s\\n", resp.ID, resp.Message)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Status]       201\n# [Content-Type] application/json\n# [Response]     ID=777, Msg=Объект успешно создан'}], 'under_the_hood': 'Поскольку `json.NewEncoder` пишет прямо в `w`, вызов `WriteHeader` до него гарантирует правильный HTTP-код в заголовке пакета.', 'pitfalls': 'Если вызвать `json.NewEncoder(w).Encode(data)` до `w.WriteHeader(...)`, ответ уйдет со статусом `200 OK` вместо `201 Created`.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему json.NewEncoder быстрее json.Marshal при отправке ответа?»\n**Ответ:** `json.Marshal` аллоцирует буфер байт в куче, заполняет его, а затем `w.Write` копирует его в буфер сокета. `json.NewEncoder` пишет чанки напрямую в сетевой буфер без промежуточной аллокации.'}, {'num': 68, 'title': 'Продвинутый Request ID Middleware с типизированным контекстным ключом', 'task': '**[Высокая сложность]**: Напиши middleware, который добавляет ID запроса (Request ID) в контекст запроса (`r.WithContext`), чтобы его можно было извлечь в логгере позже.', 'theory': 'Для исключения коллизий контекстных ключей в Go объявляют специальный неэкспортируемый тип:\n```go\ntype contextKey struct{}\nvar reqIDKey = contextKey{}\n```\nMiddleware генерирует ID, обогащает контекст и пробрасывает обновленный `*http.Request` дальше.', 'step_by_step': '1. Объявим приватный тип ключа.\n2. Создадим функции `ContextWithRequestID` и `RequestIDFromContext`.\n3. Реализуем `RequestIDMiddleware`.\n4. Проверим извлечение ID внутри хендлера.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"context"\n\t"crypto/rand"\n\t"encoding/hex"\n\t"fmt"\n\t"net/http"\n\t"net/http/httptest"\n)\n\ntype reqKeyType struct{}\n\nvar reqKey = reqKeyType{}\n\nfunc ContextWithRequestID(ctx context.Context, id string) context.Context {\n\treturn context.WithValue(ctx, reqKey, id)\n}\n\nfunc RequestIDFromContext(ctx context.Context) string {\n\tif id, ok := ctx.Value(reqKey).(string); ok {\n\t\treturn id\n\t}\n\treturn ""\n}\n\nfunc RequestIDMiddleware(next http.Handler) http.Handler {\n\treturn http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {\n\t\tbuf := make([]byte, 6)\n\t\t_, _ = rand.Read(buf)\n\t\treqID := hex.EncodeToString(buf)\n\n\t\tw.Header().Set("X-Request-ID", reqID)\n\t\tctx := ContextWithRequestID(r.Context(), reqID)\n\t\tnext.ServeHTTP(w, r.WithContext(ctx))\n\t})\n}\n\nfunc handler(w http.ResponseWriter, r *http.Request) {\n\tid := RequestIDFromContext(r.Context())\n\tfmt.Printf("[Business Service] Обработка транзакции с CorrelationID: %s\\n", id)\n\tfmt.Fprint(w, "DONE")\n}\n\nfunc main() {\n\tts := httptest.NewServer(RequestIDMiddleware(http.HandlerFunc(handler)))\n\tdefer ts.Close()\n\n\tresp, _ := http.Get(ts.URL)\n\tresp.Body.Close()\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Business Service] Обработка транзакции с CorrelationID: ...'}], 'under_the_hood': '`context.WithValue` создает узел связного списка контекстов `valueCtx`. Поиск значения выполняется вверх по дереву контекстов за $O(D)$, где $D$ — глубина вложенности.', 'pitfalls': 'Не помещайте слишком много значений в `context.WithValue`: поиск по длинной цепочке замедляет работу. Для группы параметров лучше использовать единую структуру.', 'bigtech_interview': '**Вопрос с собеседования:** «Каковы лучшие практики хранения данных в context.Context?»\n**Ответ:** В контексте хранят данные с областью видимости запроса (Request-scoped): ID трассировки, данные аутентифицированного пользователя, дедлайны отмены. Нельзя хранить необязательные параметры бизнес-логики или зависимости сервисов (БД, клиенты).'}, {'num': 69, 'title': 'Тюнинг таймаутов http.Server и отражение атак типа Slowloris', 'task': 'Настройте таймауты самого сервера: `ReadTimeout`, `WriteTimeout`, `IdleTimeout` в `http.Server`. Объясните, как они защищают от Slowloris-атак.', 'theory': 'Атака Slowloris: атакующий открывает тысячи TCP-соединений и шлет HTTP-заголовки со скоростью 1 байт в 10 секунд. Сервер держит сокеты открытыми, пока не закончатся доступные файловые дескрипторы.\nЗащитные таймауты `http.Server`:\n- `ReadHeaderTimeout` — предельное время на чтение заголовков (лучшая защита от Slowloris).\n- `ReadTimeout` — полное время на чтение заголовков и тела запроса.\n- `WriteTimeout` — время от конца чтения запроса до конца записи ответа.\n- `IdleTimeout` — максимальное время удержания неактивного соединения в пуле Keep-Alive.', 'step_by_step': '1. Создадим структуру `&http.Server` со строгими таймаутами.\n2. Объясним назначение каждого таймаута.\n3. Проверим запуск сервера.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"net/http"\n\t"time"\n)\n\nfunc main() {\n\tmux := http.NewServeMux()\n\tmux.HandleFunc("/ping", func(w http.ResponseWriter, r *http.Request) {\n\t\tfmt.Fprint(w, "pong")\n\t})\n\n\tserver := &http.Server{\n\t\tAddr:              ":8080",\n\t\tHandler:           mux,\n\t\tReadHeaderTimeout: 2 * time.Second,  // Защита от Slowloris\n\t\tReadTimeout:       5 * time.Second,  // Чтение всего тела\n\t\tWriteTimeout:      10 * time.Second, // Запись ответа\n\t\tIdleTimeout:       30 * time.Second, // Keep-Alive пауза\n\t\tMaxHeaderBytes:    1 << 20,          // 1 MB лимит заголовков\n\t}\n\n\tfmt.Println("[Security Configured] Сервер настроен с защитой от Slowloris:")\n\tfmt.Printf("  • ReadHeaderTimeout: %v\\n", server.ReadHeaderTimeout)\n\tfmt.Printf("  • ReadTimeout:       %v\\n", server.ReadTimeout)\n\tfmt.Printf("  • WriteTimeout:      %v\\n", server.WriteTimeout)\n\tfmt.Printf("  • IdleTimeout:       %v\\n", server.IdleTimeout)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Security Configured] Сервер настроен с защитой от Slowloris:\n#   • ReadHeaderTimeout: 2s\n#   • ReadTimeout:       5s\n#   • WriteTimeout:      10s\n#   • IdleTimeout:       30s'}], 'under_the_hood': 'Рантайм Go использует системный таймер сетевого дедлайна `conn.SetReadDeadline` и `conn.SetWriteDeadline` на уровне сетевого сокета ОС.', 'pitfalls': 'В HTTP/2 протоколе `WriteTimeout` отсчитывается не на запрос, а на всё TCP-соединение, что при стриминге может вызвать неожиданный разрыв сессии.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему ReadHeaderTimeout важнее ReadTimeout для отражения Slowloris?»\n**Ответ:** `ReadTimeout` начинает отсчитываться после принятия сокета, но если клиент шлет большое легитимное тело файла, `ReadTimeout` должен быть большим. `ReadHeaderTimeout` ограничивает строго чтение заголовков: заголовки всегда короткие, поэтому лимит в 2-5 секунд мгновенно сбрасывает атакующих Slowloris.'}, {'num': 70, 'title': 'Реализация непрерывного SSE-канала с контролем отключения клиента', 'task': 'Реализуйте Server-Sent Events (SSE): хендлер, который не закрывает соединение, выставляет заголовок `text/event-stream` и периодически отправляет клиенту обновления через `http.Flusher`.', 'theory': 'SSE с циклом событий обязан слушать `<-r.Context().Done()`:\nЕсли клиент отключается, таймер или канал тиков останавливается, освобождая горутину.', 'step_by_step': '1. Установим `Content-Type: text/event-stream`.\n2. Создадим тикер `time.NewTicker`.\n3. В `select` будем слушать тикер и `r.Context().Done()`.\n4. Проверим корректное завершение при закрытии соединения.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"context"\n\t"fmt"\n\t"net/http"\n\t"net/http/httptest"\n\t"time"\n)\n\nfunc sseStream(w http.ResponseWriter, r *http.Request) {\n\tflusher, ok := w.(http.Flusher)\n\tif !ok {\n\t\thttp.Error(w, "Streaming unsupported", http.StatusInternalServerError)\n\t\treturn\n\t}\n\n\tw.Header().Set("Content-Type", "text/event-stream")\n\tw.Header().Set("Cache-Control", "no-cache")\n\n\tticker := time.NewTicker(15 * time.Millisecond)\n\tdefer ticker.Stop()\n\n\tfor {\n\t\tselect {\n\t\tcase <-r.Context().Done():\n\t\t\tfmt.Println("[SSE Server] Клиент отключился, завершаем стрим")\n\t\t\treturn\n\t\tcase t := <-ticker.C:\n\t\t\tfmt.Fprintf(w, "data: ping at %s\\n\\n", t.Format("15:04:05.000"))\n\t\t\tflusher.Flush()\n\t\t}\n\t}\n}\n\nfunc main() {\n\tts := httptest.NewServer(http.HandlerFunc(sseStream))\n\tdefer ts.Close()\n\n\tctx, cancel := context.WithTimeout(context.Background(), 40*time.Millisecond)\n\tdefer cancel()\n\n\treq, _ := http.NewRequestWithContext(ctx, http.MethodGet, ts.URL, nil)\n\tresp, _ := http.DefaultClient.Do(req)\n\tif resp != nil {\n\t\tresp.Body.Close()\n\t}\n\n\ttime.Sleep(50 * time.Millisecond)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [SSE Server] Клиент отключился, завершаем стрим'}], 'under_the_hood': 'Когда соединение закрывается, Netpoller фиксирует событие `HUP/ERR`, и рантайм закрывает канал `Done()` контекста.', 'pitfalls': 'Если забыть вызвать `flusher.Flush()`, события будут скапливаться во внутреннем буфере и клиент не увидит real-time обновлений.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему SSE потребляет меньше ресурсов, чем WebSocket?»\n**Ответ:** SSE работает по обычному однонаправленному HTTP-каналу, не требует сложного фрейминга, маскирования битов и поддержки двустороннего протокола, а также идеально кэшируется и проксируется существующими балансировщиками (Nginx/Envoy).'}, {'num': 71, 'title': 'Монтирование статического каталога с index.html через http.FileServer', 'task': '**Раздача статики**: Создай папку `static` с файлом `index.html`. Используй `http.FileServer(http.Dir("static"))`, чтобы твой сервер отдавал файлы прямо в браузер.', 'theory': 'Если клиент запрашивает корень директории (`/`), `http.FileServer` автоматически проверяет наличие файла `index.html` и отдает его содержимое со статусом `200 OK`.', 'step_by_step': '1. Создадим временную папку `static` с файлом `index.html`.\n2. Запустим `http.FileServer(http.Dir(dir))`.\n3. Выполним GET-запрос к корню `/`.\n4. Проверим получение HTML-страницы.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"io"\n\t"net/http"\n\t"net/http/httptest"\n\t"os"\n\t"path/filepath"\n)\n\nfunc main() {\n\tstaticDir, _ := os.MkdirTemp("", "web_static_*")\n\tdefer os.RemoveAll(staticDir)\n\n\thtmlContent := "<html><body><h1>Go Web App</h1></body></html>"\n\t_ = os.WriteFile(filepath.Join(staticDir, "index.html"), []byte(htmlContent), 0644)\n\n\tfs := http.FileServer(http.Dir(staticDir))\n\tts := httptest.NewServer(fs)\n\tdefer ts.Close()\n\n\tresp, _ := http.Get(ts.URL + "/")\n\tbody, _ := io.ReadAll(resp.Body)\n\tresp.Body.Close()\n\n\tfmt.Printf("[Status]       %d\\n", resp.StatusCode)\n\tfmt.Printf("[Content-Type] %s\\n", resp.Header.Get("Content-Type"))\n\tfmt.Printf("[HTML]         %s\\n", string(body))\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Status]       200\n# [Content-Type] text/html; charset=utf-8\n# [HTML]         <html><body><h1>Go Web App</h1></body></html>'}], 'under_the_hood': '`FileServer` определяет тип контента по расширению `.html` через таблицу соответствий в стандартном пакете `mime`.', 'pitfalls': 'Если `index.html` отсутствует, `FileServer` сгенерирует HTML-листинг файлов каталога, что может раскрыть конфиденциальные файлы.', 'bigtech_interview': '**Вопрос с собеседования:** «Как запретить листинг директорий в стандартном http.FileServer?»\n**Ответ:** Реализовать собственную обертку над `http.FileSystem`: переопределить метод `Open(name string)` и, если `file.Stat().IsDir()`, проверять наличие `index.html`. Если его нет — возвращать ошибку `os.ErrNotExist` (404 Not Found).'}, {'num': 72, 'title': 'Rate Limiter Middleware: ограничение пиковых запросов с ответом 429 Too Many Requests', 'task': '**Rate Limiting Middleware**: Используй пакет `golang.org/x/time/rate`. Создай мидлварь, которая позволяет делать не более 10 запросов в секунду (на весь сервер или по IP). Если лимит превышен — отвечай `429 Too Many Requests`.', 'theory': 'Пакет `rate.Limiter` использует алгоритм Token Bucket:\n- `rate.Limit(10)` — 10 токенов в секунду.\n- `burst: 10` — максимальная емкость корзины.\nМетод `limiter.Allow()` возвращает `false`, если в корзине нет свободных токенов.', 'step_by_step': '1. Создадим структуру простого лимитера на мьютексе и атомике.\n2. Реализуем проверку `Allow()`.\n3. При превышении вернем статус `http.StatusTooManyRequests`.\n4. Проверим отклонение избыточных запросов.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"net/http"\n\t"net/http/httptest"\n\t"sync/atomic"\n)\n\ntype SimpleLimiter struct {\n\tavailable atomic.Int32\n}\n\nfunc NewSimpleLimiter(burst int32) *SimpleLimiter {\n\tl := &SimpleLimiter{}\n\tl.available.Store(burst)\n\treturn l\n}\n\nfunc (l *SimpleLimiter) Allow() bool {\n\tfor {\n\t\tcur := l.available.Load()\n\t\tif cur <= 0 {\n\t\t\treturn false\n\t\t}\n\t\tif l.available.CompareAndSwap(cur, cur-1) {\n\t\t\treturn true\n\t\t}\n\t}\n}\n\nfunc RateLimitMiddleware(limiter *SimpleLimiter, next http.Handler) http.Handler {\n\treturn http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {\n\t\tif !limiter.Allow() {\n\t\t\tw.Header().Set("Retry-After", "5")\n\t\t\thttp.Error(w, "429 Too Many Requests", http.StatusTooManyRequests)\n\t\t\treturn\n\t\t}\n\t\tnext.ServeHTTP(w, r)\n\t})\n}\n\nfunc main() {\n\tlimiter := NewSimpleLimiter(2) // Лимит всего 2 запроса\n\thandler := RateLimitMiddleware(limiter, http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {\n\t\tfmt.Fprint(w, "OK")\n\t}))\n\n\tts := httptest.NewServer(handler)\n\tdefer ts.Close()\n\n\tfor i := 1; i <= 4; i++ {\n\t\tres, _ := http.Get(ts.URL)\n\t\tfmt.Printf("Запрос %d: Статус %d\\n", i, res.StatusCode)\n\t\tres.Body.Close()\n\t}\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Запрос 1: Статус 200\n# Запрос 2: Статус 200\n# Запрос 3: Статус 429\n# Запрос 4: Статус 429'}], 'under_the_hood': '`CompareAndSwap` (CAS) выполняет атомарное декрементирование счетчика без мьютексов в свободном от блокировок цикле (Lock-free).', 'pitfalls': 'Для предотвращения DoS-атак на память сервера старые неактивные IP-адреса из мапы лимитеров необходимо периодически удалять фоновым воркером (Garbage Collection).', 'bigtech_interview': '**Вопрос с собеседования:** «В чем отличие алгоритмов Leaky Bucket и Token Bucket?»\n**Ответ:** `Token Bucket` позволяет накапливать токены во время простоя и пропускать резкие всплески трафика (burst) в пределах емкости корзины. `Leaky Bucket` пропускает трафик строго с фиксированной скоростью (константный rate), сглаживая любые пики нагрузки.'}, {'num': 73, 'title': 'CORS Middleware: обработка Preflight OPTIONS запросов и настройка заголовков', 'task': 'Напишите middleware для CORS (Cross-Origin Resource Sharing), который добавляет нужные заголовки (`Access-Control-Allow-Origin` и т.д.) и корректно обрабатывает `OPTIONS` preflight-запросы.', 'theory': 'Политика CORS (Cross-Origin Resource Sharing):\nБраузер перед выполнением сложных запросов (с кастомными заголовками или методами PUT/DELETE) отправляет предварительный Preflight-запрос методом `OPTIONS`.\nСервер обязан:\n1. Установить заголовки: `Access-Control-Allow-Origin`, `Access-Control-Allow-Methods`, `Access-Control-Allow-Headers`, `Access-Control-Max-Age`.\n2. На запрос `OPTIONS` вернуть `204 No Content` и не передавать управление дальше в хендлер.', 'step_by_step': '1. Напишем `CORSMiddleware`.\n2. Проверим метод: если `r.Method == http.MethodOptions`, отдадим 204.\n3. Добавим CORS-заголовки ко всем ответам.\n4. Протестируем Preflight и обычный GET.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"net/http"\n\t"net/http/httptest"\n)\n\nfunc CORSMiddleware(next http.Handler) http.Handler {\n\treturn http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {\n\t\tw.Header().Set("Access-Control-Allow-Origin", "*")\n\t\tw.Header().Set("Access-Control-Allow-Methods", "GET, POST, PUT, DELETE, OPTIONS")\n\t\tw.Header().Set("Access-Control-Allow-Headers", "Content-Type, Authorization, X-Requested-With")\n\t\tw.Header().Set("Access-Control-Max-Age", "86400")\n\n\t\t// Обработка Preflight OPTIONS запроса\n\t\tif r.Method == http.MethodOptions {\n\t\t\tw.WriteHeader(http.StatusNoContent)\n\t\t\treturn\n\t\t}\n\n\t\tnext.ServeHTTP(w, r)\n\t})\n}\n\nfunc main() {\n\thandler := CORSMiddleware(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {\n\t\tfmt.Fprint(w, "CORS Protected Data")\n\t}))\n\n\tts := httptest.NewServer(handler)\n\tdefer ts.Close()\n\n\t// 1. Preflight запрос\n\tpreReq, _ := http.NewRequest(http.MethodOptions, ts.URL, nil)\n\tpreReq.Header.Set("Origin", "https://frontend.company.ru")\n\tpreReq.Header.Set("Access-Control-Request-Method", "PUT")\n\tres1, _ := http.DefaultClient.Do(preReq)\n\tres1.Body.Close()\n\n\tfmt.Printf("[Preflight OPTIONS] Status: %d, Allowed-Methods: %s\\n",\n\t\tres1.StatusCode, res1.Header.Get("Access-Control-Allow-Methods"))\n\n\t// 2. Обычный GET запрос\n\tres2, _ := http.Get(ts.URL)\n\tres2.Body.Close()\n\tfmt.Printf("[Standard GET]      Status: %d, Allowed-Origin: %s\\n",\n\t\tres2.StatusCode, res2.Header.Get("Access-Control-Allow-Origin"))\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Preflight OPTIONS] Status: 204, Allowed-Methods: GET, POST, PUT, DELETE, OPTIONS\n# [Standard GET]      Status: 200, Allowed-Origin: *'}], 'under_the_hood': 'Заголовок `Access-Control-Max-Age: 86400` кэширует результат Preflight-проверки в браузере на 24 часа, избавляя от лишних сетевых запросов перед каждым PUT/DELETE.', 'pitfalls': 'Если на сервере включена передача кук `Access-Control-Allow-Credentials: true`, то `Access-Control-Allow-Origin: *` использовать запрещено — браузер отклонит ответ. Необходимо указывать точный Origin.', 'bigtech_interview': '**Вопрос с собеседования:** «Защищает ли CORS API-сервер от прямого взлома злоумышленником через curl или Postman?»\n**Ответ:** Нет. CORS — это исключительно браузерный механизм защиты пользователя (защита от кражи данных скриптами на сторонних сайтах). Утилиты вроде `curl` или Python-скрипты игнорируют CORS-заголовки и шлют любые запросы напрямую.'}, {'num': 74, 'title': 'Интеграционное тестирование через httptest.NewServer на динамическом локальном порту', 'task': 'Используйте `net/http/httptest.NewServer`, чтобы поднять реальный мок-сервер на случайном порту для тестирования вашего HTTP-клиента.', 'theory': '`httptest.NewServer(handler)` запускает реальный HTTP-сервер на случайно выделенном свободном порту петлевого интерфейса `127.0.0.1`. Это исключает конфликты номеров портов при параллельном запуске сотен тестов `go test -p 8 ./...`.', 'step_by_step': '1. Создадим `httptest.NewServer` с тестовым обработчиком.\n2. Проверим динамический адрес `server.URL`.\n3. Выполним реальный сетевой запрос через `http.Client`.\n4. Закроем сервер через `defer server.Close()`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"io"\n\t"net/http"\n\t"net/http/httptest"\n)\n\nfunc main() {\n\t// Поднимаем изолированный сервер на случайном свободном порту\n\tmockServer := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {\n\t\tw.Header().Set("Content-Type", "application/json")\n\t\tfmt.Fprint(w, `{"status":"mocked_ok"}`)\n\t}))\n\tdefer mockServer.Close()\n\n\tfmt.Printf("[TestServer] Сервер запущен на адресе: %s\\n", mockServer.URL)\n\n\tresp, err := http.Get(mockServer.URL)\n\tif err != nil {\n\t\tpanic(err)\n\t}\n\tdefer resp.Body.Close()\n\n\tbody, _ := io.ReadAll(resp.Body)\n\tfmt.Printf("[Client] Ответ получен: %s\\n", string(body))\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [TestServer] Сервер запущен на адресе: http://127.0.0.1:...\n# [Client] Ответ получен: {"status":"mocked_ok"}'}], 'under_the_hood': '`httptest.NewServer` использует системный вызов `net.Listen("tcp", "127.0.0.1:0")`. Порт `0` указывает ядру ОС выделить первый доступный непривилегированный порт (эфемеридный порт).', 'pitfalls': 'Всегда вызывайте `defer server.Close()`, иначе останутся незакрытые TCP-листенеры и горутины.', 'bigtech_interview': '**Вопрос с собеседования:** «Когда использовать httptest.NewServer, а когда httptest.NewRecorder?»\n**Ответ:** `NewRecorder` быстрее, так как не открывает сокеты и тестирует хендлер в памяти (для юнит-тестов обработчиков). `NewServer` нужен, когда требуется протестировать реальное сетевое взаимодействие, HTTP-клиент, работу с пулом соединений или редиректы.'}, {'num': 75, 'title': 'Молниеносное юнит-тестирование хендлеров в памяти через httptest.NewRecorder', 'task': 'Используйте `httptest.NewRecorder()` для тестирования HTTP-хендлеров "в памяти" без реального запуска сети, сокетов и портов.', 'theory': '`httptest.ResponseRecorder` реализует интерфейс `http.ResponseWriter`, перехватывая статус-код, заголовки и тело в буфер памяти. В связке с `httptest.NewRequest` это позволяет запускать тысячи тестов хендлеров за доли секунды.', 'step_by_step': '1. Создадим целевую функцию-хендлер.\n2. Создадим фиктивный запрос `req := httptest.NewRequest(...)`.\n3. Создадим рекордер `rec := httptest.NewRecorder()`.\n4. Вызовем метод `handler(rec, req)` и проверим `rec.Code` и `rec.Body`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"net/http"\n\t"net/http/httptest"\n)\n\nfunc Greeter(w http.ResponseWriter, r *http.Request) {\n\tuser := r.URL.Query().Get("user")\n\tif user == "" {\n\t\thttp.Error(w, "missing user parameter", http.StatusBadRequest)\n\t\treturn\n\t}\n\tw.WriteHeader(http.StatusOK)\n\tfmt.Fprintf(w, "Hello, %s!", user)\n}\n\nfunc main() {\n\t// 1. Тест успешного сценария\n\treq1 := httptest.NewRequest(http.MethodGet, "/greet?user=Gopher", nil)\n\trec1 := httptest.NewRecorder()\n\n\tGreeter(rec1, req1)\n\n\tfmt.Printf("[Test 1: Success] Code: %d, Body: %s\\n", rec1.Code, rec1.Body.String())\n\n\t// 2. Тест сценария с ошибкой 400\n\treq2 := httptest.NewRequest(http.MethodGet, "/greet", nil)\n\trec2 := httptest.NewRecorder()\n\n\tGreeter(rec2, req2)\n\n\tfmt.Printf("[Test 2: Failure] Code: %d, Body: %s", rec2.Code, rec2.Body.String())\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Test 1: Success] Code: 200, Body: Hello, Gopher!\n# [Test 2: Failure] Code: 400, Body: missing user parameter'}], 'under_the_hood': '`httptest.NewRecorder()` не совершает сетевых вызовов `socket()`, `bind()`, `listen()`. Он пишет данные в обычный `bytes.Buffer` в куче.', 'pitfalls': 'Рекордер не эмулирует разрыв сети клиентом — для тестирования отмены контекста нужно явно передавать отмененный контекст в `req`.', 'bigtech_interview': '**Вопрос с собеседования:** «Как протестировать хендлер, использующий r.PathValue("id"), с помощью httptest?»\n**Ответ:** Начиная с Go 1.22, при вызове хендлера напрямую через `handler.ServeHTTP(rec, req)` контекст роутера отсутствует. Чтобы параметры пути заполнились, нужно либо тестировать хендлер через роутер `mux.ServeHTTP(rec, req)`, либо использовать `r.SetPathValue("id", "123")`.'}, {'num': 76, 'title': 'Экономия ресурсов сервера: ранний выход из вычислений по отмене контекста', 'task': '**Контекст запроса (Отключение клиента)**: Внутри хендлера запусти долгую операцию (цикл на 5 секунд). Если клиент закроет вкладку до конца операции, `r.Context().Done()` закроется. Напиши `select`, который прервёт вычисления и сэкономит ресурсы сервера.', 'theory': 'Если запрос требует длительных вычислений (например, генерация отчета в цикле по 1000 порциям), хендлер обязан проверять контекст на каждой итерации:\n```go\nselect {\ncase <-ctx.Done():\n    return\ndefault:\n}\n```', 'step_by_step': '1. Создадим обработчик с 5 итерациями вычислений.\n2. На каждом шаге проверим `ctx.Done()`.\n3. Сымитируем отключение клиента на второй итерации.\n4. Убедимся, что цикл немедленно прервался.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"context"\n\t"fmt"\n\t"net/http"\n\t"net/http/httptest"\n\t"time"\n)\n\nfunc loopComputeHandler(w http.ResponseWriter, r *http.Request) {\n\tctx := r.Context()\n\tfmt.Println("[Compute] Старт многоэтапной обработки...")\n\n\tfor step := 1; step <= 5; step++ {\n\t\tselect {\n\t\tcase <-ctx.Done():\n\t\t\tfmt.Printf("[Compute] Вычисления прерваны на шаге %d/5! Сохранили CPU!\\n", step)\n\t\t\treturn\n\t\tdefault:\n\t\t\t// Эмуляция шага вычислений\n\t\t\ttime.Sleep(20 * time.Millisecond)\n\t\t\tfmt.Printf(" -> Завершен этап %d/5\\n", step)\n\t\t}\n\t}\n\n\tfmt.Fprint(w, "Результат вычислений")\n}\n\nfunc main() {\n\tts := httptest.NewServer(http.HandlerFunc(loopComputeHandler))\n\tdefer ts.Close()\n\n\t// Прерываем клиентский запрос через 35 мс (успеет только 1-й шаг)\n\tctx, cancel := context.WithTimeout(context.Background(), 35*time.Millisecond)\n\tdefer cancel()\n\n\treq, _ := http.NewRequestWithContext(ctx, http.MethodGet, ts.URL, nil)\n\t_, _ = http.DefaultClient.Do(req)\n\n\ttime.Sleep(100 * time.Millisecond)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Compute] Старт многоэтапной обработки...\n#  -> Завершен этап 1/5\n# [Compute] Вычисления прерваны на шаге 2/5! Сохранили CPU!'}], 'under_the_hood': 'Неблокирующий `select` с `default:` проверяет канал без задержки. Если канал не закрыт, мгновенно переходит в ветку `default`.', 'pitfalls': 'Если долгая операция блокируется внутри сторонней библиотеки без поддержки контекста, прервать горутину до ее естественного завершения невозможно.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему в Go нельзя принудительно убить горутину снаружи?»\n**Ответ:** Принудительное завершение горутины (как в thread.stop) привело бы к повреждению разделяемой памяти: мьютексы остались бы заблокированными навсегда (дедлок), а частично обновленные структуры — в некорректном состоянии. Кооперативная отмена через контекст гарантирует безопасность.'}, {'num': 77, 'title': 'Инженерные Table-Driven тесты REST API со всеми краевыми сценариями', 'task': 'Напишите Table-Driven Tests для вашего REST API, проверяя различные сценарии (успех, невалидный JSON, отсутствие ресурса, неверный метод).', 'theory': 'Table-Driven Testing (табличное тестирование) — идиоматический стандарт тестирования в Go. Набор тест-кейсов описывается в срезе анонимных структур, содержащих входные параметры и ожидаемый результат.', 'step_by_step': '1. Опишем таблицу тест-кейсов `tests := []struct{ name, method, url, body, expectedCode }`.\n2. Запустим тесты в цикле.\n3. Проверим коды возврата 200, 400, 404, 405.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"bytes"\n\t"fmt"\n\t"net/http"\n\t"net/http/httptest"\n)\n\nfunc APIRouter() http.Handler {\n\tmux := http.NewServeMux()\n\tmux.HandleFunc("GET /items/{id}", func(w http.ResponseWriter, r *http.Request) {\n\t\tid := r.PathValue("id")\n\t\tif id == "404" {\n\t\t\thttp.NotFound(w, r)\n\t\t\treturn\n\t\t}\n\t\tw.WriteHeader(http.StatusOK)\n\t\tfmt.Fprint(w, `{"id":1,"name":"Item"}`)\n\t})\n\tmux.HandleFunc("POST /items", func(w http.ResponseWriter, r *http.Request) {\n\t\tif r.Body == nil || r.ContentLength == 0 {\n\t\t\thttp.Error(w, "empty body", http.StatusBadRequest)\n\t\t\treturn\n\t\t}\n\t\tw.WriteHeader(http.StatusCreated)\n\t})\n\treturn mux\n}\n\nfunc main() {\n\trouter := APIRouter()\n\n\tcases := []struct {\n\t\tname         string\n\t\tmethod       string\n\t\tpath         string\n\t\tpayload      string\n\t\texpectedCode int\n\t}{\n\t\t{"Успешный GET", http.MethodGet, "/items/1", "", http.StatusOK},\n\t\t{"Несуществующий ресурс", http.MethodGet, "/items/404", "", http.StatusNotFound},\n\t\t{"Пустое тело POST", http.MethodPost, "/items", "", http.StatusBadRequest},\n\t\t{"Неверный метод (DELETE на GET)", http.MethodDelete, "/items/1", "", http.StatusMethodNotAllowed},\n\t}\n\n\tfor _, tc := range cases {\n\t\tvar reqBody *bytes.Buffer\n\t\tif tc.payload != "" {\n\t\t\treqBody = bytes.NewBufferString(tc.payload)\n\t\t} else {\n\t\t\treqBody = &bytes.Buffer{}\n\t\t}\n\n\t\treq := httptest.NewRequest(tc.method, tc.path, reqBody)\n\t\trec := httptest.NewRecorder()\n\n\t\trouter.ServeHTTP(rec, req)\n\n\t\tif rec.Code == tc.expectedCode {\n\t\t\tfmt.Printf("✔ [PASS] %-30s | Code: %d\\n", tc.name, rec.Code)\n\t\t} else {\n\t\t\tfmt.Printf("✘ [FAIL] %-30s | Expected: %d, Got: %d\\n", tc.name, tc.expectedCode, rec.Code)\n\t\t}\n\t}\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# ✔ [PASS] Успешный GET                   | Code: 200\n# ✔ [PASS] Несуществующий ресурс          | Code: 404\n# ✔ [PASS] Пустое тело POST               | Code: 400\n# ✔ [PASS] Неверный метод (DELETE на GET) | Code: 405'}], 'under_the_hood': 'Табличные тесты изолируют данные от проверочной логики, позволяя добавлять десятки новых тест-кейсов добавлением одной строки в срез.', 'pitfalls': 'В юнит-тестах с `t.Parallel()` переменную цикла `tc := tc` до Go 1.22 необходимо было переопределять в теле цикла во избежание захвата одной ссылки всеми горутинами.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему табличные тесты предпочтительнее множества разрозненных функций TestXxx?»\n**Ответ:** Табличные тесты компактны, устраняют дублирование тестового кода подготовки запросов, обеспечивают 100% покрытие краевых условий и легко интегрируются с Fuzzing-тестами.'}, {'num': 78, 'title': 'Сериализация сложных вложенных структур и слайсов в форматированный JSON', 'task': 'Сериализуйте сложную структуру (вложенные объекты, слайсы) в JSON и отправьте как ответ сервера. Клиент должен десериализовать её и красиво вывести.', 'theory': 'Сложные модели данных в API:\n- Вложенные структуры (композиция).\n- Слайсы дочерних сущностей.\n- Теги `json:"name,omitempty"`.\nИспользование `json.NewEncoder(w).Encode(obj)` автоматически поддерживает рекурсивную сериализацию произвольной глубины вложенности.', 'step_by_step': '1. Опишем структуры `Company`, `Department`, `Employee`.\n2. Заполним иерархическую структуру.\n3. Отправим JSON-ответ клиенту.\n4. Клиент десериализует и выведет данные.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"encoding/json"\n\t"fmt"\n\t"net/http"\n\t"net/http/httptest"\n)\n\ntype Employee struct {\n\tID   int    `json:"id"`\n\tName string `json:"name"`\n\tRole string `json:"role"`\n}\n\ntype Department struct {\n\tName  string     `json:"name"`\n\tStaff []Employee `json:"staff"`\n}\n\ntype Organization struct {\n\tOrgName string       `json:"org_name"`\n\tDepts   []Department `json:"departments"`\n}\n\nfunc orgHandler(w http.ResponseWriter, r *http.Request) {\n\torg := Organization{\n\t\tOrgName: "FinTech Holdings",\n\t\tDepts: []Department{\n\t\t\t{\n\t\t\t\tName: "Core Backend",\n\t\t\t\tStaff: []Employee{\n\t\t\t\t\t{1, "Дмитрий", "Tech Lead"},\n\t\t\t\t\t{2, "Анна", "Senior Go Dev"},\n\t\t\t\t},\n\t\t\t},\n\t\t},\n\t}\n\n\tw.Header().Set("Content-Type", "application/json")\n\t_ = json.NewEncoder(w).Encode(org)\n}\n\nfunc main() {\n\tts := httptest.NewServer(http.HandlerFunc(orgHandler))\n\tdefer ts.Close()\n\n\tresp, _ := http.Get(ts.URL)\n\tdefer resp.Body.Close()\n\n\tvar result Organization\n\t_ = json.NewDecoder(resp.Body).Decode(&result)\n\n\tfmt.Println("Организация:", result.OrgName)\n\tfor _, d := range result.Depts {\n\t\tfmt.Println(" Отдел:", d.Name)\n\t\tfor _, e := range d.Staff {\n\t\t\tfmt.Printf("   • [%d] %s (%s)\\n", e.ID, e.Name, e.Role)\n\t\t}\n\t}\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Организация: FinTech Holdings\n#  Отдел: Core Backend\n#    • [1] Дмитрий (Tech Lead)\n#    • [2] Анна (Senior Go Dev)'}], 'under_the_hood': 'Рефлексивный энкодер Go рекурсивно обходит поля структур, следуя указателям и тегам сериализации.', 'pitfalls': 'Циклические ссылки в структурах вызовут бесконечную рекурсию и панику `runtime: goroutine stack exceeds limit` при маршалинге в JSON.', 'bigtech_interview': '**Вопрос с собеседования:** «Зачем нужен тег `json:",omitempty"` и когда он может навредить?»\n**Ответ:** `omitempty` скрывает поле в JSON, если оно равно нулевому значению типа (`false`, `0`, `""`, `nil`). Он может навредить в boolean полях: например, если клиент передает `is_active: false`, поле с `omitempty` будет пропущено и сервер не сможет отличить «не передано» от «передано false». Решение — использовать указатель `*bool`.'}, {'num': 79, 'title': 'Инициализация производственного http.Server с жесткими сетевыми таймаутами', 'task': '**Кастомный `http.Server`**: Вместо `ListenAndServe` создай структуру `srv := &http.Server{Addr: ":8080", Handler: mux, ReadTimeout: 5 * time.Second, WriteTimeout: 10 * time.Second}`. Это защитит сервер от "медленных клиентов" (Slowloris attack).', 'theory': 'Запуск `http.ListenAndServe(":8080", nil)` — частая ошибка новичков, так как сервер создается с бесконечными таймаутами. В продакшене обязательно создается экземпляр `&http.Server` со строгой конфигурацией.', 'step_by_step': '1. Создадим экземпляр `http.Server`.\n2. Зададим `ReadTimeout`, `WriteTimeout` и `IdleTimeout`.\n3. Запустим сервер и проверим доступность.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"net/http"\n\t"net/http/httptest"\n\t"time"\n)\n\nfunc NewProductionServer(handler http.Handler) *http.Server {\n\treturn &http.Server{\n\t\tHandler:           handler,\n\t\tReadHeaderTimeout: 2 * time.Second,\n\t\tReadTimeout:       5 * time.Second,\n\t\tWriteTimeout:      10 * time.Second,\n\t\tIdleTimeout:       60 * time.Second,\n\t}\n}\n\nfunc main() {\n\tmux := http.NewServeMux()\n\tmux.HandleFunc("/health", func(w http.ResponseWriter, r *http.Request) {\n\t\tfmt.Fprint(w, "healthy")\n\t})\n\n\tsrv := NewProductionServer(mux)\n\tts := httptest.NewServer(srv.Handler)\n\tdefer ts.Close()\n\n\tres, _ := http.Get(ts.URL + "/health")\n\tdefer res.Body.Close()\n\n\tfmt.Println("Промышленный сервер успешно ответил со статусом:", res.StatusCode)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Промышленный сервер успешно ответил со статусом: 200'}], 'under_the_hood': 'Таймауты сокетов транслируются в таймеры рантайма, интегрированные с Netpoller.', 'pitfalls': 'Слишком маленький `WriteTimeout` может оборвать отправку тяжелого файла легитимному клиенту с медленным мобильным интернетом.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему линтер gosec ругается на вызовы http.ListenAndServe?»\n**Ответ:** Правило `G114 (CWE-676)` предупреждает о риске DoS: вызов `http.ListenAndServe` не позволяет задать `ReadHeaderTimeout`, что делает сервис уязвимым перед Slowloris атаками. Линтер требует явного создания `&http.Server`.'}, {'num': 80, 'title': 'Мокирование внешних HTTP-зависимостей через кастомный RoundTripper', 'task': 'Создайте мок для внешней зависимости (например, стороннего API), подменяя `http.Client.Transport` на кастомный `RoundTripper`, который возвращает заранее заготовленные ответы.', 'theory': 'Интерфейс `http.RoundTripper`:\n```go\ntype RoundTripper interface {\n    RoundTrip(*Request) (*Response, error)\n}\n```\nПодменяя `client.Transport` в тестах, можно полностью перехватить исходящие HTTP-запросы и вернуть синтетический `*http.Response` без реальных сетевых вызовов.', 'step_by_step': '1. Создадим тип-адаптер `RoundTripFunc`.\n2. Подменим `client.Transport` мок-транспортом.\n3. Вернем сгенерированный `http.Response` с JSON.\n4. Проверим чтение ответа клиентом.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"bytes"\n\t"fmt"\n\t"io"\n\t"net/http"\n)\n\ntype MockTransport func(req *http.Request) (*http.Response, error)\n\nfunc (m MockTransport) RoundTrip(req *http.Request) (*http.Response, error) {\n\treturn m(req)\n}\n\nfunc main() {\n\t// Подменяем сетевой транспорт мок-функцией\n\tmockClient := &http.Client{\n\t\tTransport: MockTransport(func(req *http.Request) (*http.Response, error) {\n\t\t\tfmt.Printf("[Mock Interceptor] Перехвачен запрос к: %s\\n", req.URL.String())\n\n\t\t\tmockJSON := `{"payment_status": "APPROVED", "transaction_id": "tx_8899"}`\n\t\t\tresp := &http.Response{\n\t\t\t\tStatusCode: http.StatusOK,\n\t\t\t\tStatus:     "200 OK",\n\t\t\t\tBody:       io.NopCloser(bytes.NewBufferString(mockJSON)),\n\t\t\t\tHeader:     make(http.Header),\n\t\t\t\tRequest:    req,\n\t\t\t}\n\t\t\tresp.Header.Set("Content-Type", "application/json")\n\t\t\treturn resp, nil\n\t\t}),\n\t}\n\n\t// Клиент делает запрос на внешний недоступный домен\n\tresp, err := mockClient.Get("https://api.payment-gateway.com/charge")\n\tif err != nil {\n\t\tpanic(err)\n\t}\n\tdefer resp.Body.Close()\n\n\tbody, _ := io.ReadAll(resp.Body)\n\tfmt.Printf("[Client Received]: %s\\n", string(body))\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Mock Interceptor] Перехвачен запрос к: https://api.payment-gateway.com/charge\n# [Client Received]: {"payment_status": "APPROVED", "transaction_id": "tx_8899"}'}], 'under_the_hood': '`io.NopCloser` оборачивает `*bytes.Buffer` в интерфейс `io.ReadCloser` с пустым методом `Close()`, идеально подходя для создания синтетических `resp.Body`.', 'pitfalls': 'В возвращаемом `http.Response` поле `Request` обязательно должно указывать на исходный `req`, иначе сторонние парсеры могут запаниковать.', 'bigtech_interview': '**Вопрос с собеседования:** «В чем преимущество мокирования через RoundTripper по сравнению с httptest.NewServer?»\n**Ответ:** Мокирование через `RoundTripper` выполняется полностью в памяти (In-Memory) без выделения портов TCP и сетевых сокетов, работает мгновенно и не требует перенастройки базовых URL клиентов.'}]
